export const LUAT_QC: Record<string, string> = {
  "_adlaw-from-notebook": "﻿# Trích xuất luật quảng cáo từ NotebookLM (notebook fa72c143-baca-42b5-a976-a7e1245b5dfa)\n> Tạo tự động 2026-06-29 10:21 bằng extract-ad-law.ps1. Mỗi mục = 1 truy vấn hẹp.\n\n\n## 1. Hành vi quảng cáo bị cấm (Điều 8)\n\nContinuing conversation 8090ff64...\nAnswer:\nDưới đây là danh sách TỪNG hành vi bị cấm trong hoạt động quảng cáo, được trích\nnguyên văn theo **Điều 8 Luật Quảng cáo số 16/2012/QH13** và các phần sửa đổi, \nbãi bỏ tại **Luật sửa đổi, bổ sung một số điều của Luật Quảng cáo số \n75/2025/QH15**:\n\n- **Khoản 1 Điều 8 Luật Quảng cáo số 16/2012/QH13:** \"Quảng cáo những sản phẩm,\nhàng hóa, dịch vụ quy định tại Điều 7 của Luật này\" [1].\n- **Khoản 2 Điều 8 Luật Quảng cáo số 16/2012/QH13:** \"Quảng cáo làm tiết lộ bí \nmật nhà nước, phương hại đến độc lập, chủ quyền quốc gia, an ninh, quốc phòng\" \n[1].\n- **Khoản 3 Điều 8 Luật Quảng cáo số 16/2012/QH13 (được sửa đổi tại điểm a \nkhoản 4 Điều 1 Luật số 75/2025/QH15):** \"Quảng cáo trái với truyền thống lịch \nsử, văn hóa, đạo đức xã hội.\" [2].\n- **Khoản 4 Điều 8 Luật Quảng cáo số 16/2012/QH13:** \"Quảng cáo làm ảnh hưởng \nđến mỹ quan đô thị, trật tự an toàn giao thông, an toàn xã hội\" [1].\n- **Khoản 5 Điều 8 Luật Quảng cáo số 16/2012/QH13:** \"Quảng cáo gây ảnh hưởng \nxấu đến sự tôn nghiêm đối với Quốc kỳ, Quốc huy, Quốc ca, Đảng kỳ, anh hùng dân\ntộc, danh nhân văn hóa, lãnh tụ, lãnh đạo Đảng, Nhà nước\" [1].\n- **Khoản 6 Điều 8 Luật Quảng cáo số 16/2012/QH13:** \"Quảng cáo có tính chất kỳ\nthị dân tộc, phân biệt chủng tộc, xâm phạm tự do tín ngưỡng, tôn giáo, định \nkiến về giới, về người khuyết tật\" [1].\n- **Khoản 7 Điều 8 Luật Quảng cáo số 16/2012/QH13:** \"Quảng cáo xúc phạm uy \ntín, danh dự, nhân phẩm của tổ chức, cá nhân\" [1].\n- **Khoản 8 Điều 8 Luật Quảng cáo số 16/2012/QH13:** \"Quảng cáo có sử dụng hình\nảnh, lời nói, chữ viết của cá nhân khi chưa được cá nhân đó đồng ý, trừ trường \nhợp được pháp luật cho phép\" [1].\n- **Khoản 9 Điều 8 Luật Quảng cáo số 16/2012/QH13:** \"Quảng cáo không đúng hoặc\ngây nhầm lẫn về khả năng kinh doanh, khả năng cung cấp sản phẩm, hàng hóa, dịch\nvụ của tổ chức, cá nhân kinh doanh sản phẩm, hàng hóa, dịch vụ; về số lượng, \nchất lượng, giá, công dụng, kiểu dáng, bao bì, nhãn hiệu, xuất xứ, chủng loại, \nphương thức phục vụ, thời hạn bảo hành của sản phẩm, hàng hoá, dịch vụ đã đăng \nký hoặc đã được công bố\" [1].\n- **Khoản 10 Điều 8 Luật Quảng cáo số 16/2012/QH13 (được sửa đổi tại điểm b \nkhoản 4 Điều 1 Luật số 75/2025/QH15):** \"Quảng cáo so sánh sản phẩm, hàng hóa, \ndịch vụ của mình với sản phẩm, hàng hóa, dịch vụ cùng loại của tổ chức, cá nhân\nkhác nhưng không có tài liệu hợp pháp chứng minh.\" [3].\n- **Khoản 11 Điều 8 Luật Quảng cáo số 16/2012/QH13:** \"Quảng cáo có sử dụng các\ntừ ngữ \"nhất\", \"duy nhất\", \"tốt nhất\", \"số một\" hoặc từ ngữ có ý nghĩa tương tự\nmà không có tài liệu hợp pháp chứng minh theo quy định của Bộ Văn hóa, Thể thao\nvà Du lịch\" [1].\n- **Khoản 12 Điều 8 Luật Quảng cáo số 16/2012/QH13:** \"Quảng cáo có nội dung \ncạnh tranh không lành mạnh theo quy định của pháp luật về cạnh tranh\" [1].\n- **Khoản 13 Điều 8 Luật Quảng cáo số 16/2012/QH13:** Hành vi nguyên văn \"Quảng\ncáo vi phạm pháp luật về sở hữu trí tuệ\" [1] **đã bị bãi bỏ** theo khoản 12 \nĐiều 1 Luật số 75/2025/QH15 [4].\n- **Khoản 14 Điều 8 Luật Quảng cáo số 16/2012/QH13:** \"Quảng cáo tạo cho trẻ em\ncó suy nghĩ, lời nói, hành động trái với đạo đức, thuần phong mỹ tục; gây ảnh \nhưởng xấu đến sức khỏe, an toàn hoặc sự phát triển bình thường của trẻ em\" [1].\n- **Khoản 15 Điều 8 Luật Quảng cáo số 16/2012/QH13:** \"Ép buộc cơ quan, tổ \nchức, cá nhân thực hiện quảng cáo hoặc tiếp nhận quảng cáo trái ý muốn\" [1].\n- **Khoản 16 Điều 8 Luật Quảng cáo số 16/2012/QH13:** \"Treo, đặt, dán, vẽ các \nsản phẩm quảng cáo trên cột điện, trụ điện, cột tín hiệu giao thông và cây xanh\nnơi công cộng\" [1].\n\nResumed conversation: 8090ff64-55ce-4d1b-a033-e37fc1200605\n\n## 2. Quảng cáo sai/gây nhầm lẫn về công dụng-chất lượng\n\nAnswer:\nDựa vào các nguồn trong notebook, quy định về hành vi quảng cáo không đúng sự \nthật, gây nhầm lẫn hoặc hiểu nhầm về chất lượng, công dụng, tính năng (công \nnăng) của sản phẩm được trích nguyên văn như sau:\n\n*   **Khoản 9 Điều 8 Luật Quảng cáo số 16/2012/QH13** (Quy định về các hành vi \ncấm trong hoạt động quảng cáo):\n    \"Quảng cáo không đúng hoặc gây nhầm lẫn về khả năng kinh doanh, khả năng \ncung cấp sản phẩm, hàng hóa, dịch vụ của tổ chức, cá nhân kinh doanh sản phẩm, \nhàng hóa, dịch vụ; về số lượng, chất lượng, giá, công dụng, kiểu dáng, bao bì, \nnhãn hiệu, xuất xứ, chủng loại, phương thức phục vụ, thời hạn bảo hành của sản \nphẩm, hàng hoá, dịch vụ đã đăng ký hoặc đã được công bố.\" [1]\n\n*   **Khoản 1 Điều 19 Luật Quảng cáo số 16/2012/QH13 (được sửa đổi, bổ sung tại\nkhoản 11 Điều 1 Luật sửa đổi, bổ sung một số điều của Luật Quảng cáo số \n75/2025/QH15)** (Quy định về yêu cầu đối với nội dung quảng cáo):\n    \"1. Nội dung quảng cáo phải trung thực, chính xác, rõ ràng; không gây hiểu \nnhầm về tính năng, chất lượng, công dụng, tác dụng của sản phẩm, hàng hóa, dịch\nvụ.\" [2]\n\n*   **Khoản 2 Điều 4 Nghị định số 342/2025/NĐ-CP** (Quy định cụ thể đối với nội\ndung quảng cáo mỹ phẩm):\n    \"2. Quảng cáo mỹ phẩm không được gây hiểu nhầm sản phẩm đó là thuốc. Nội \ndung quảng cáo mỹ phẩm phải phù hợp với bản chất sản phẩm mỹ phẩm, phân loại \nsản phẩm và tính năng, công dụng đã được công bố theo quy định của pháp luật.\" \n[3]\n\nConversation: 8090ff64-55ce-4d1b-a033-e37fc1200605 (turn 1)\n\n## 3. Sản phẩm liên quan sức khỏe / không phải là thuốc\n\nAnswer:\nDựa vào các nguồn trong notebook, quy định về những cụm từ **BẮT BUỘC** hoặc \nnội dung/ý nghĩa **BỊ CẤM** (như cấm gây hiểu nhầm) đối với quảng cáo các sản \nphẩm, hàng hóa, dịch vụ đặc biệt (ảnh hưởng đến sức khỏe, thực phẩm, thiết bị y\ntế...) được trích nguyên văn như sau:\n\n**1. Những cụm từ BẮT BUỘC phải có trong quảng cáo:**\n\n*   **Đối với Thực phẩm:**\n    *   **Khoản 2 Điều 5 Nghị định số 342/2025/NĐ-CP:** \"Quảng cáo thực phẩm \nbảo vệ sức khoẻ phải có cụm từ: **“Thực phẩm bảo vệ sức khỏe”**; quảng cáo thực\nphẩm bổ sung phải có cụm từ: **“Thực phẩm bổ sung”**; quảng cáo thực phẩm dinh \ndưỡng y học phải có cụm từ **“Thực phẩm dinh dưỡng y học\"** và **“Sử dụng cho \nngười bệnh với sự giám sát của nhân viên y tế”**; quảng cáo thực phẩm dùng cho \nchế độ ăn đặc biệt phải có cụm từ: **“Sản phẩm dinh dưỡng cho (đối tượng cụ thể\nsử dụng sản phẩm đó)”**.\" [1]\n    *   **Điểm b Khoản 3 Điều 5 Nghị định số 342/2025/NĐ-CP** (đối với thực \nphẩm bảo vệ sức khỏe): \"Khuyến cáo **“Thực phẩm này không phải là thuốc và \nkhông có tác dụng thay thế thuốc chữa bệnh”**;\" [2]\n\n*   **Đối với Sữa và sản phẩm dinh dưỡng dùng cho trẻ nhỏ (không thuộc loại cấm\nquảng cáo):**\n    *   **Điểm a Khoản 2 Điều 6 Nghị định số 342/2025/NĐ-CP:** \"Phần đầu của \nquảng cáo phải nêu rõ **“Sản phẩm này là thức ăn bổ sung và được ăn thêm cùng \nvới sữa mẹ dùng cho trẻ trên 06 tháng tuổi”**;\" [3]\n    *   **Điểm b Khoản 2 Điều 6 Nghị định số 342/2025/NĐ-CP:** \"Khuyến cáo \n**“Sữa mẹ là thức ăn tốt nhất cho sức khỏe và sự phát triển toàn diện của trẻ \nnhỏ”**;\" [3]\n\n*   **Đối với Hóa chất, chế phẩm diệt côn trùng, diệt khuẩn dùng trong gia dụng\nvà y tế:**\n    *   **Khoản 3 Điều 7 Nghị định số 342/2025/NĐ-CP:** \"Khuyến cáo **“Đọc kỹ \nhướng dẫn sử dụng trước khi dùng”**.\" [4]\n\n*   **Đối với Thiết bị y tế, Dịch vụ khám/chữa bệnh, Thuốc bảo vệ thực vật/thú \ny, Phân bón:**\n    *   **NGUỒN KHÔNG ĐỀ CẬP** các \"cụm từ\" cụ thể (trong ngoặc kép) bắt buộc \nphải đọc/viết. Nguồn chỉ quy định bắt buộc phải cung cấp các *thông tin* (như \ntên, mục đích sử dụng, cảnh báo, tên địa chỉ cơ sở...) [5-10].\n\n**2. Quy định về ý nghĩa BỊ CẤM (cấm gây hiểu nhầm):**\n\n*   **Yêu cầu chung cho mọi sản phẩm, hàng hóa, dịch vụ:**\n    *   **Khoản 1 Điều 19 Luật Quảng cáo số 16/2012/QH13 (được sửa đổi tại \nkhoản 11 Điều 1 Luật số 75/2025/QH15):** \"Nội dung quảng cáo phải trung thực, \nchính xác, rõ ràng; **không gây hiểu nhầm về tính năng, chất lượng, công dụng, \ntác dụng của sản phẩm, hàng hóa, dịch vụ.**\" [11]\n\n*   **Đối với Mỹ phẩm:**\n    *   **Khoản 2 Điều 4 Nghị định số 342/2025/NĐ-CP:** \"**Quảng cáo mỹ phẩm \nkhông được gây hiểu nhầm sản phẩm đó là thuốc.** Nội dung quảng cáo mỹ phẩm \nphải phù hợp với bản chất sản phẩm mỹ phẩm, phân loại sản phẩm và tính năng, \ncông dụng đã được công bố theo quy định của pháp luật.\" [12]\n\n**3. Ví dụ cụm từ cấm:**\n*   **NGUỒN KHÔNG ĐỀ CẬP.** (Các văn bản pháp luật trong nguồn chỉ quy định \nnguyên tắc cấm các hành vi hoặc nội dung \"gây hiểu nhầm là thuốc\", \"gây hiểu \nnhầm về công dụng\", nhưng không liệt kê danh sách ví dụ các cụm từ cụ thể bị \ncấm).\n\nConversation: 8090ff64-55ce-4d1b-a033-e37fc1200605 (turn 1)\n\n## 4. Quảng cáo so sánh\n\nAnswer:\nDựa vào các nguồn trong notebook, quy định về hành vi quảng cáo so sánh sản \nphẩm, hàng hóa, dịch vụ với tổ chức/cá nhân khác được trích nguyên văn như sau:\n\n**1. Quy định gốc (Luật Quảng cáo 2012):**\n*   **Khoản 10 Điều 8 Luật Quảng cáo số 16/2012/QH13** (Hành vi cấm trong hoạt \nđộng quảng cáo):\n    \"Quảng cáo bằng việc sử dụng phương pháp so sánh trực tiếp về giá cả, chất \nlượng, hiệu quả sử dụng sản phẩm, hàng hóa, dịch vụ của mình với giá cả, chất \nlượng, hiệu quả sử dụng sản phẩm, hàng hóa, dịch vụ cùng loại của tổ chức, cá \nnhân khác.\" [1]\n\n**2. Điểm mới sửa đổi (Luật 2025):** \n*   **Điểm b khoản 4 Điều 1 Luật sửa đổi, bổ sung một số điều của Luật Quảng \ncáo số 75/2025/QH15** (sửa đổi, bổ sung khoản 10 Điều 8 Luật Quảng cáo số \n16/2012/QH13):\n    \"10. Quảng cáo so sánh sản phẩm, hàng hóa, dịch vụ của mình với sản phẩm, \nhàng hóa, dịch vụ cùng loại của tổ chức, cá nhân khác nhưng không có tài liệu \nhợp pháp chứng minh.\" [2, 3]\n\n**3. Điều kiện, tài liệu chứng minh bắt buộc cụ thể đối với quảng cáo so \nsánh:**\n*   **NGUỒN KHÔNG ĐỀ CẬP**. (Luật số 75/2025/QH15 chỉ quy định nguyên tắc bắt \nbuộc là phải có \"tài liệu hợp pháp chứng minh\" để không bị cấm [3], tuy nhiên \ncác văn bản hướng dẫn trong nguồn không có điều/khoản nào định nghĩa chi tiết \nhay liệt kê cụ thể loại tài liệu nào là hợp lệ dành riêng cho hình thức quảng \ncáo so sánh này).\n\nConversation: 8090ff64-55ce-4d1b-a033-e37fc1200605 (turn 1)\n\n## 5. Yêu cầu trung thực + nhận diện quảng cáo\n\nAnswer:\nDựa vào các nguồn trong notebook, quy định về tính trung thực, chính xác của \nnội dung quảng cáo và yêu cầu phải nhận diện/phân biệt được nội dung quảng cáo \nvới các nội dung khác được trích nguyên văn như sau:\n\n**1. Về tính trung thực, chính xác của nội dung/thông tin quảng cáo:**\n\n*   **Điểm a khoản 2 Điều 12 Luật Quảng cáo số 16/2012/QH13** (Quy định về \nnghĩa vụ của người quảng cáo):\n    \"a) Cung cấp cho người kinh doanh dịch vụ quảng cáo hoặc người phát hành \nquảng cáo thông tin cần thiết, trung thực, chính xác về cơ quan, tổ chức, cá \nnhân, sản phẩm, hàng hóa, dịch vụ, các tài liệu liên quan đến điều kiện quảng \ncáo và chịu trách nhiệm về các thông tin đó;\" [1]\n*   **Điểm b khoản 1 Điều 13 Luật Quảng cáo số 16/2012/QH13** (Quy định về \nquyền của người kinh doanh dịch vụ quảng cáo):\n    \"b) Được người quảng cáo cung cấp thông tin trung thực, chính xác về tổ \nchức, cá nhân, sản phẩm, hàng hóa, dịch vụ được quảng cáo và các tài liệu liên \nquan đến điều kiện quảng cáo;\" [2]\n*   **Điểm a khoản 1 Điều 15a Luật Quảng cáo số 16/2012/QH13 (được bổ sung tại \nkhoản 8 Điều 1 Luật số 75/2025/QH15)** (Quy định về quyền của người chuyển tải \nsản phẩm quảng cáo):\n    \"a) Được người quảng cáo cung cấp thông tin trung thực, đầy đủ, chính xác \nvề tổ chức, cá nhân, sản phẩm, hàng hóa, dịch vụ được quảng cáo và các tài liệu\nliên quan đến điều kiện quảng cáo;\" [3]\n*   **Khoản 1 Điều 16 Luật Quảng cáo số 16/2012/QH13** (Quy định về quyền của \nngười tiếp nhận quảng cáo):\n    \"1. Được thông tin trung thực về chất lượng, tính năng, tác dụng của sản \nphẩm, hàng hóa, dịch vụ.\" [4]\n*   **Khoản 1a Điều 18 Luật Quảng cáo số 16/2012/QH13 (được bổ sung tại khoản \n10 Điều 1 Luật số 75/2025/QH15)** (Quy định về tiếng nói, chữ viết trong quảng \ncáo):\n    \"1a. Từ ngữ bằng tiếng Việt trong sản phẩm quảng cáo phải bảo đảm giữ gìn \nsự trong sáng của tiếng Việt, rõ ràng, dễ hiểu và thể hiện chính xác nội dung \ncần truyền đạt.\" [5]\n*   **Khoản 1 Điều 19 Luật Quảng cáo số 16/2012/QH13 (được sửa đổi tại khoản 11\nĐiều 1 Luật số 75/2025/QH15)** (Yêu cầu đối với nội dung quảng cáo):\n    \"1. Nội dung quảng cáo phải trung thực, chính xác, rõ ràng; không gây hiểu \nnhầm về tính năng, chất lượng, công dụng, tác dụng của sản phẩm, hàng hóa, dịch\nvụ.\" [6]\n\n**2. Về việc nội dung phải nhận diện được là quảng cáo (phân biệt với nội dung \nphi quảng cáo):**\n\n*   **Khoản 1 Điều 21 Luật Quảng cáo số 16/2012/QH13 (được sửa đổi tại khoản 13\nĐiều 1 Luật số 75/2025/QH15)** (Quảng cáo trên báo in):\n    \"1. Diện tích quảng cáo không được vượt quá 30% tổng diện tích một ấn phẩm \nbáo hoặc 40% tổng diện tích một ấn phẩm tạp chí, trừ báo, tạp chí chuyên quảng \ncáo, phụ trương quảng cáo; phải có dấu hiệu phân biệt nội dung quảng cáo với \ncác nội dung khác.\" [7]\n*   **Khoản 1 Điều 22 Luật Quảng cáo số 16/2012/QH13 (được sửa đổi tại điểm a \nkhoản 14 Điều 1 Luật số 75/2025/QH15)** (Quảng cáo trên báo nói, báo hình):\n    \"1. Thời lượng quảng cáo trên kênh chương trình cung cấp theo phương thức \nquảng bá không được vượt quá 10% tổng thời lượng phát sóng một ngày của các \nkênh chương trình, trừ thời lượng quảng cáo trên kênh chương trình chuyên quảng\ncáo; phải có dấu hiệu phân biệt nội dung quảng cáo với các nội dung khác.\" [7]\n*   **Khoản 2 Điều 22 Luật Quảng cáo số 16/2012/QH13 (được sửa đổi tại điểm a \nkhoản 14 Điều 1 Luật số 75/2025/QH15)** (Quảng cáo trên báo nói, báo hình):\n    \"2. Thời lượng quảng cáo trên kênh truyền hình chương trình cung cấp theo \nphương thức trả tiền không được vượt quá 5% tổng thời lượng phát sóng một ngày \ncủa các kênh chương trình, trừ thời lượng quảng cáo trên kênh chương trình \nchuyên quảng cáo; phải có dấu hiệu phân biệt nội dung quảng cáo với các nội \ndung khác.\" [8]\n*   **Khoản 5 Điều 22 Luật Quảng cáo số 16/2012/QH13 (được sửa đổi tại điểm b \nkhoản 14 Điều 1 Luật số 75/2025/QH15)** (Quảng cáo trên báo nói, báo hình):\n    \"5. Khi thể hiện sản phẩm quảng cáo kèm theo nội dung thông tin chính thức \nbằng hình thức chạy chữ hoặc một chuỗi hình ảnh chuyển động thì diện tích quảng\ncáo phải bảo đảm không được vượt quá 10% diện tích màn hình; phải có dấu hiệu \nphân biệt nội dung quảng cáo với các nội dung khác và không được làm ảnh hưởng \ntới nội dung chính trong chương trình. Quảng cáo bằng hình thức này không tính \nvào thời lượng quảng cáo của báo hình. Khi thể hiện sản phẩm quảng cáo kèm theo\nnội dung thông tin chính thức bằng hình thức chạy chữ thì sản phẩm quảng cáo \nphải được thể hiện phía sát cạnh dưới màn hình.\" [9]\n*   **Khoản 2 Điều 23 Luật Quảng cáo số 16/2012/QH13 (được sửa đổi tại khoản 15\nĐiều 1 Luật số 75/2025/QH15)** (Quảng cáo trên mạng):\n    *   \"a) Phải có dấu hiệu nhận diện rõ ràng bằng chữ số, chữ viết, ký hiệu, \nhình ảnh, âm thanh để phân biệt giữa nội dung quảng cáo với các nội dung khác \nkhông phải quảng cáo;\" [10]\n    *   \"d) Tổ chức, doanh nghiệp cung cấp dịch vụ mạng xã hội phải cung cấp \ncho người sử dụng tính năng để phân biệt nội dung quảng cáo với các nội dung \nkhác;\" [11]\n    *   \"đ) Người sử dụng dịch vụ mạng xã hội khi thực hiện quảng cáo phải có \ndấu hiệu phân biệt nội dung quảng cáo hoặc được tài trợ với nội dung khác do \nmình cung cấp.\" [11]\n*   **Điểm b khoản 4 Điều 19 Nghị định số 342/2025/NĐ-CP:**\n    \"b) Khi thực hiện quảng cáo qua công cụ tìm kiếm cần có dấu hiệu phân biệt \nkết quả hiển thị được tài trợ và kết quả tìm kiếm thông thường.\" [12]\n\nConversation: 8090ff64-55ce-4d1b-a033-e37fc1200605 (turn 1)\n\n## 6. Người chuyển tải / người nổi tiếng (Điều 15a)\n\nAnswer:\nDựa vào các nguồn trong notebook, quy định về nghĩa vụ của người chuyển tải sản\nphẩm quảng cáo và người có ảnh hưởng (về việc kiểm chứng, điều kiện được quảng \ncáo và hợp đồng) theo Điều 15a được trích nguyên văn như sau:\n\n**1. Nghĩa vụ chung của người chuyển tải sản phẩm quảng cáo:**\n*Trích nguyên văn khoản 2 Điều 15a Luật Quảng cáo số 16/2012/QH13 (được bổ sung\ntại khoản 9 Điều 1 Luật sửa đổi, bổ sung một số điều của Luật Quảng cáo số \n75/2025/QH15):*\n\"2. Người chuyển tải sản phẩm quảng cáo có các nghĩa vụ sau:\na) Tuân thủ các quy định của pháp luật về bảo vệ quyền lợi người tiêu dùng và \ncác quy định khác của pháp luật về việc cung cấp thông tin liên quan đến tính \nnăng, chất lượng sản phẩm, hàng hóa, dịch vụ khi thực hiện quảng cáo; thực hiện\nnghĩa vụ về thuế khi phát sinh doanh thu từ dịch vụ quảng cáo theo quy định của\npháp luật về thuế [1];\nb) Cung cấp tài liệu liên quan đến nội dung quảng cáo khi cơ quan nhà nước có \nthẩm quyền yêu cầu [2];\nc) Chịu trách nhiệm trước pháp luật trong trường hợp nội dung quảng cáo không \nbảo đảm các yêu cầu theo quy định tại Điều 19 của Luật này [2];\nd) Thực hiện nghĩa vụ khác theo quy định của pháp luật [2];\nđ) Người chuyển tải sản phẩm quảng cáo trên mạng thực hiện quy định tại các \nđiểm a, b, c, d khoản này và các quy định có liên quan tại Điều 23 của Luật này\n[2].\"\n\n**2. Nghĩa vụ của người có ảnh hưởng (bao gồm yêu cầu kiểm chứng và khi nào \nđược quảng cáo):**\n*Trích nguyên văn khoản 3 Điều 15a Luật Quảng cáo số 16/2012/QH13 (được bổ sung\ntại khoản 9 Điều 1 Luật sửa đổi, bổ sung một số điều của Luật Quảng cáo số \n75/2025/QH15):*\n\"3. Người có ảnh hưởng theo quy định của pháp luật về bảo vệ quyền lợi người \ntiêu dùng khi chuyển tải sản phẩm quảng cáo có nghĩa vụ quy định tại khoản 2 \nĐiều này và các nghĩa vụ sau đây [2]:\na) **Xác minh về độ tin cậy của người quảng cáo; kiểm tra tài liệu liên quan \nđến sản phẩm, hàng hóa, dịch vụ quảng cáo; trường hợp chưa sử dụng hoặc chưa \nhiểu rõ về sản phẩm, hàng hóa, dịch vụ thì không được giới thiệu về sản phẩm, \nhàng hóa, dịch vụ** [3];\nb) Thông báo về việc quảng cáo ngay trước và trong khi thực hiện hoạt động \nquảng cáo [3].\"\n*(Lưu ý: Nguồn không sử dụng thuật ngữ \"người nổi tiếng\" trong Điều 15a mà sử \ndụng thuật ngữ pháp lý là \"người có ảnh hưởng\").*\n\n**3. Về quy định liên quan đến Hợp đồng đối với người chuyển tải sản phẩm quảng\ncáo theo Điều 15a:**\n**NGUỒN KHÔNG ĐỀ CẬP**. (Trong nội dung Điều 15a được cung cấp hoàn toàn không \nnhắc đến yếu tố hợp đồng đối với nhóm đối tượng này) [1-4].\n\nConversation: 8090ff64-55ce-4d1b-a033-e37fc1200605 (turn 1)\n\n## 7. Cụm từ tuyệt đối bị cấm\n\nAnswer:\nDựa vào các nguồn trong notebook, việc sử dụng các từ ngữ \"nhất\", \"duy nhất\", \n\"tốt nhất\", \"số một\"... là hành vi **BỊ CẤM NẾU KHÔNG CÓ** tài liệu hợp pháp \nchứng minh. Quy định cụ thể và các điều kiện về tài liệu hợp pháp chứng minh \nđược trích nguyên văn như sau:\n\n**1. Quy định cấm nếu không có tài liệu chứng minh:**\n*   **Khoản 11 Điều 8 Luật Quảng cáo số 16/2012/QH13** (Quy định về hành vi cấm\ntrong hoạt động quảng cáo):\n    \"Quảng cáo có sử dụng các từ ngữ \"nhất\", \"duy nhất\", \"tốt nhất\", \"số một\" \nhoặc từ ngữ có ý nghĩa tương tự mà không có tài liệu hợp pháp chứng minh theo \nquy định của Bộ Văn hóa, Thể thao và Du lịch\" [1].\n\n**2. Quy định chi tiết về \"Tài liệu hợp pháp chứng minh\" và điều kiện sử \ndụng:**\n\nHiện tại, có 2 văn bản hướng dẫn chi tiết nội dung này trong nguồn (Thông tư \n10/2013/TT-BVHTTDL hiện hành và Thông tư 12/2026/TT-BVHTTDL có hiệu lực từ ngày\n05/07/2026 thay thế Thông tư 10):\n\n*   **Trích nguyên văn Điều 2 Thông tư số 10/2013/TT-BVHTTDL (Văn bản hiện \nhành):**\n    \"1. Tài liệu hợp pháp quy định tại khoản 11 Điều 8 của Luật Quảng cáo bao \ngồm:\n    a) Kết quả khảo sát thị trường của các tổ chức được thành lập và hoạt động \nhợp pháp có chức năng nghiên cứu thị trường;\n    b) Giấy chứng nhận hoặc các giấy tờ tương tự tại các cuộc thi, triển lãm có\nquy mô khu vực hoặc toàn quốc bình chọn và công nhận các loại sản phẩm, hàng \nhóa, dịch vụ đó là \"nhất\", \"duy nhất\", \"tốt nhất\", \"số một\" hoặc các từ ngữ có \ný nghĩa tương tự.\n    2. Thời gian sử dụng tài liệu hợp pháp chứng minh từ \"nhất\", \"duy nhất\", \n\"tốt nhất\", \"số một\" hoặc các từ ngữ có ý nghĩa tương tự trên các sản phẩm \nquảng cáo là 01 (một) năm kể từ ngày tổ chức, cá nhân được cấp giấy chứng nhận \nhoặc nhận kết quả khảo sát thị trường.\n    3. Trên sản phẩm quảng cáo phải thể hiện đầy đủ, rõ ràng, chính xác tên tài\nliệu hợp pháp quy định tại Khoản 1 Điều này.\" [2].\n\n*   **Trích nguyên văn Điều 3 Thông tư số 12/2026/TT-BVHTTDL (Văn bản sắp có \nhiệu lực từ 05/07/2026):**\n    \"1. Từ ngữ có ý nghĩa tương tự theo quy định tại khoản 11 Điều 8 Luật Quảng\ncáo là các từ, cụm từ bằng tiếng Việt hoặc tiếng nước ngoài khẳng định vị thế \ndẫn đầu, tính độc bản, tính tuyệt đối của sản phẩm, hàng hóa, dịch vụ.\n    2. Tài liệu hợp pháp chứng minh quy định tại khoản 11 Điều 8 Luật Quảng cáo\nlà một trong các loại tài liệu sau đây:\n    a) Kết quả khảo sát thị trường của tổ chức được thành lập và hoạt động hợp \npháp, có chức năng nghiên cứu thị trường;\n    b) Giấy chứng nhận do cơ quan, tổ chức có thẩm quyền cấp tại các cuộc thi, \ntriển lãm, giải thưởng quy mô toàn quốc, khu vực hoặc quốc tế bình chọn, xếp \nhạng, đánh giá và công nhận các sản phẩm, hàng hóa, dịch vụ đó là “nhất”, “duy \nnhất”, “tốt nhất”, “số một” hoặc các từ ngữ ý nghĩa tương tự.\n    3. Thời gian sử dụng tài liệu quy định tại khoản 1 và khoản 2 Điều này trên\ncác sản phẩm quảng cáo theo thời hạn của giấy chứng nhận hoặc kết quả khảo sát \nthị trường.\n    4. Trên sản phẩm quảng cáo phải thể hiện rõ ràng, chính xác tên tài liệu; \nsố, ký hiệu và thời gian công bố kết quả khảo sát thị trường hoặc thời gian cấp\ngiấy chứng nhận quy định tại khoản 1 và khoản 2 Điều này.\n    5. Tài liệu quy định tại khoản 1 và khoản 2 Điều này chỉ được sử dụng khi:\n    a) Bảo đảm tính độc lập, khách quan, trung thực;\n    b) Không gây nhầm lẫn cho người tiêu dùng và phù hợp với quy định của pháp \nluật có liên quan.\" [3-5].\n\nConversation: 8090ff64-55ce-4d1b-a033-e37fc1200605 (turn 1)\n\n## 8. Telesales - cuộc gọi quảng cáo (NĐ 91/2020)\n\nAnswer:\nDựa vào các nguồn trong notebook, đối với yêu cầu của bạn về quy định **GỌI \nĐIỆN** quảng cáo tới khách hàng và trích dẫn Nghị định 91/2020/NĐ-CP:\n\n**NGUỒN KHÔNG ĐỀ CẬP.**\n\n*(Ghi chú thêm từ nguồn: Các văn bản được cung cấp hoàn toàn không chứa Nghị \nđịnh 91/2020/NĐ-CP. Bên cạnh đó, Luật Quảng cáo số 16/2012/QH13 chỉ quy định về\nđiều kiện đồng ý trước, khung giờ (07 giờ đến 22 giờ), số lần tối đa (không quá\n3) và quyền từ chối dành riêng cho hình thức **\"gửi tin nhắn, thư điện tử quảng\ncáo\"** tại khoản 1 Điều 24 [1, 2], không có bất kỳ điều/khoản nào trong nguồn \nquy định về hành vi **gọi điện/cuộc gọi** quảng cáo).*\n\nConversation: 8090ff64-55ce-4d1b-a033-e37fc1200605 (turn 1)\n\n## 9. Tin nhắn quảng cáo SMS/Zalo (NĐ 91/2020)\n\nAnswer:\n**Điều kiện đồng ý trước (opt-in):**\n**Điểm a khoản 1 Điều 24 Luật Quảng cáo số 16/2012/QH13:** \"Tổ chức, cá nhân \nchỉ được phép gửi tin nhắn và thư điện tử quảng cáo **khi có sự đồng ý trước \ncủa người nhận**;\" [1].\n\n**Thời gian được gửi và Tần suất:**\n**Điểm b khoản 1 Điều 24 Luật Quảng cáo số 16/2012/QH13:** \"Nhà cung cấp dịch \nvụ thông tin điện tử, viễn thông chỉ được phép gửi tin nhắn, thư điện tử có nội\ndung quảng cáo về các dịch vụ của mình; **chỉ được gửi tin nhắn quảng cáo đến \nđiện thoại trong khoảng thời gian từ 07 giờ đến 22 giờ; không được gửi quá ba \ntin nhắn quảng cáo đến một số điện thoại**, quá ba thư điện tử đến một địa chỉ \nthư điện tử **trong vòng 24 giờ**, trừ trường hợp có thỏa thuận khác với người \nnhận;\" [1, 2].\n\n**Cơ chế từ chối (opt-out):**\n**Điểm c khoản 1 Điều 24 Luật Quảng cáo số 16/2012/QH13:** \"Tổ chức, cá nhân \nquảng cáo **phải bảo đảm cho người nhận có khả năng từ chối quảng cáo; phải \nchấm dứt ngay việc gửi tin nhắn, thư điện tử quảng cáo nếu người nhận thông báo\ntừ chối quảng cáo và không được thu phí dịch vụ** đối với thông báo từ chối của\nngười nhận.\" [2].\n\n**Gắn nhãn nhận diện quảng cáo (vd [QC]):**\n**NGUỒN KHÔNG ĐỀ CẬP**.\n\nConversation: 8090ff64-55ce-4d1b-a033-e37fc1200605 (turn 1)\n\n## 10. Mức xử phạt vi phạm\n\nAnswer:\n**NGUỒN KHÔNG ĐỀ CẬP**. \n\n*(Ghi chú: Các văn bản trong notebook không có Nghị định quy định xử phạt vi \nphạm hành chính (như Nghị định 38/2021/NĐ-CP) hay bất kỳ điều/khoản nào liệt kê\nsố tiền xử phạt cụ thể cho từng hành vi vi phạm. Nguồn chỉ có quy định mang \ntính nguyên tắc về việc xử lý vi phạm, trích nguyên văn tại **Khoản 4 Điều 11 \nLuật Quảng cáo số 16/2012/QH13** như sau: \"Chính phủ quy định cụ thể về hành \nvi, hình thức và mức xử phạt vi phạm hành chính trong hoạt động quảng cáo\" \n[1]).*\n\nConversation: 8090ff64-55ce-4d1b-a033-e37fc1200605 (turn 1)\n\n## 11. Quảng cáo trên mạng / xuyên biên giới\n\nAnswer:\nDựa vào các nguồn trong notebook, quy định riêng về quảng cáo trên mạng, nền \ntảng số và xuyên biên giới được quy định rất chi tiết (đặc biệt là sau khi sửa \nđổi, bổ sung năm 2025). Dưới đây là trích nguyên văn đầy đủ các Điều/Khoản liên\nquan:\n\n**1. Định nghĩa về hoạt động cung cấp dịch vụ quảng cáo xuyên biên giới**\n*Trích nguyên văn khoản 14 Điều 2 Luật Quảng cáo số 16/2012/QH13 (được bổ sung \ntại điểm d khoản 1 Điều 1 Luật sửa đổi, bổ sung một số điều của Luật Quảng cáo \nsố 75/2025/QH15)* [1]:\n\"14. Hoạt động cung cấp dịch vụ quảng cáo xuyên biên giới tại Việt Nam là việc \ntổ chức, cá nhân tại nước ngoài sử dụng hệ thống thiết bị cung cấp dịch vụ đặt \nngoài lãnh thổ Việt Nam để cung cấp dịch vụ quảng cáo cho người sử dụng tại \nViệt Nam qua Internet.\"\n\n**2. Quy định gốc về quảng cáo trên báo điện tử, trang thông tin điện tử và \nquảng cáo xuyên biên giới (Luật 2012)**\n*Trích nguyên văn Điều 23 Luật Quảng cáo số 16/2012/QH13* [2]:\n\"**Điều 23. Quảng cáo trên báo điện tử và trang thông tin điện tử**\n1. Quảng cáo trên báo điện tử phải tuân theo các quy định sau:\na) Không được thiết kế, bố trí phần quảng cáo lẫn vào phần nội dung tin;\nb) Đối với những quảng cáo không ở vùng cố định, phải thiết kế để độc giả có \nthể chủ động tắt hoặc mở quảng cáo, thời gian chờ tắt hoặc mở quảng cáo tối đa \nlà 1,5 giây.\n2. Quảng cáo trên trang thông tin điện tử của cơ quan nhà nước thực hiện theo \nquy định tại khoản 1 Điều này.\n3. Quảng cáo trên trang thông tin điện tử của tổ chức, cá nhân nước ngoài kinh \ndoanh dịch vụ quảng cáo xuyên biên giới có phát sinh doanh thu quảng cáo tại \nViệt Nam phải tuân thủ các quy định của Luật này và các quy định khác của pháp \nluật có liên quan.\n4. Chính phủ quy định chi tiết khoản 3 Điều này.\"\n\n**3. Quy định mới toàn diện về Quảng cáo trên mạng, nền tảng số và xuyên biên \ngiới (được sửa đổi toàn bộ năm 2025)**\n*Trích nguyên văn Điều 23 Luật Quảng cáo số 16/2012/QH13 (được sửa đổi tại \nkhoản 13 Điều 1 Luật số 75/2025/QH15)* [3-11]:\n\"**Điều 23. Quảng cáo trên mạng**\n1. Hoạt động quảng cáo trên mạng bao gồm: Quảng cáo trên báo điện tử, trang \nthông tin điện tử, mạng xã hội, ứng dụng trực tuyến, nền tảng số có kết nối \nInternet.\n2. Hoạt động quảng cáo trên mạng phải tuân thủ các quy định sau đây:\na) Phải có dấu hiệu nhận diện rõ ràng bằng chữ số, chữ viết, ký hiệu, hình ảnh,\nâm thanh để phân biệt giữa nội dung quảng cáo với các nội dung khác không phải \nquảng cáo;\nb) Đối với những quảng cáo không ở vùng cố định, phải có tính năng, biểu tượng \ndễ nhận biết cho phép người tiếp nhận quảng cáo tắt quảng cáo, thông báo nội \ndung quảng cáo vi phạm cho nhà cung cấp dịch vụ, từ chối xem nội dung quảng cáo\nkhông phù hợp;\nc) Đối với những quảng cáo có chứa đường dẫn đến nội dung khác thì nội dung \nđược dẫn đến phải tuân thủ quy định của pháp luật; người kinh doanh dịch vụ \nquảng cáo, người phát hành quảng cáo có giải pháp kiểm tra, giám sát nội dung \nđược dẫn đến;\nd) Tổ chức, doanh nghiệp cung cấp dịch vụ mạng xã hội phải cung cấp cho người \nsử dụng tính năng để phân biệt nội dung quảng cáo với các nội dung khác;\nđ) Người sử dụng dịch vụ mạng xã hội khi thực hiện quảng cáo phải có dấu hiệu \nphân biệt nội dung quảng cáo hoặc được tài trợ với nội dung khác do mình cung \ncấp.\n3. Người quảng cáo, người kinh doanh dịch vụ quảng cáo, người phát hành quảng \ncáo, người chuyển tải sản phẩm quảng cáo tham gia hoạt động quảng cáo trên mạng\ncó quyền, nghĩa vụ theo quy định tại các điều 12, 13, 14 và 15a của Luật này và\nphải tuân thủ:\na) Quy định của pháp luật về quảng cáo, an ninh mạng, bảo vệ dữ liệu cá nhân, \nbảo vệ quyền lợi người tiêu dùng, bảo vệ trẻ em, quản lý, cung cấp, sử dụng \ndịch vụ Internet và thông tin trên mạng; phải đăng ký thuế, kê khai, nộp thuế \nđối với doanh thu phát sinh từ dịch vụ quảng cáo theo quy định của pháp luật về\nthuế;\nb) Không đặt sản phẩm quảng cáo vào trong, bên cạnh, liền sau hoặc trước nội \ndung vi phạm pháp luật; không quảng cáo trên trang thông tin điện tử, mạng xã \nhội, ứng dụng trực tuyến, nền tảng số vi phạm pháp luật;\nc) Không hợp tác quảng cáo với tổ chức, cá nhân, trang thông tin điện tử, mạng \nxã hội, ứng dụng trực tuyến, nền tảng số và tài khoản, kênh nội dung, trang \ncộng đồng, nhóm cộng đồng trên mạng xã hội đã được cơ quan nhà nước có thẩm \nquyền công khai thông báo vi phạm pháp luật;\nd) Thực hiện việc ngăn chặn, gỡ bỏ thông tin vi phạm pháp luật theo yêu cầu của\ncơ quan nhà nước có thẩm quyền; cung cấp thông tin về tổ chức, cá nhân liên \nquan tới hoạt động quảng cáo trên mạng có dấu hiệu vi phạm pháp luật theo yêu \ncầu của cơ quan nhà nước có thẩm quyền;\nđ) Chấp hành các biện pháp xử phạt vi phạm hành chính và biện pháp xử lý khác \ncủa cơ quan, người có thẩm quyền khi vi phạm pháp luật về quảng cáo.\n4. Người quảng cáo, người phát hành quảng cáo, người chuyển tải sản phẩm quảng \ncáo khi giao kết hợp đồng với người kinh doanh dịch vụ quảng cáo trên mạng có \nquyền và nghĩa vụ sau:\na) Yêu cầu người kinh doanh dịch vụ quảng cáo tuân thủ quy định tại điểm b \nkhoản 3 Điều này;\nb) Yêu cầu người kinh doanh dịch vụ quảng cáo có giải pháp kỹ thuật để người \nquảng cáo, người phát hành quảng cáo tại Việt Nam có thể kiểm soát và loại bỏ \ncác sản phẩm quảng cáo vi phạm pháp luật trên hệ thống cung cấp dịch vụ.\n5. Người kinh doanh dịch vụ quảng cáo trên mạng có trách nhiệm sau:\na) Thông báo thông tin liên hệ với cơ quan nhà nước có thẩm quyền;\nb) Xác minh danh tính của người quảng cáo, yêu cầu người quảng cáo cung cấp \ngiấy chứng nhận đăng ký kinh doanh hoặc tài liệu pháp lý hợp lệ;\nc) Lưu trữ thông tin, hồ sơ về hoạt động quảng cáo, cung cấp thông tin khi cơ \nquan nhà nước có thẩm quyền yêu cầu;\nd) Có giải pháp kỹ thuật để kiểm soát và loại bỏ các sản phẩm quảng cáo vi phạm\npháp luật trên hệ thống cung cấp dịch vụ;\nđ) Lưu trữ các thông tin về quy tắc của phương thức phân phối quảng cáo, thuật \ntoán phân phối quảng cáo được sử dụng để phát hành quảng cáo trên mạng;\ne) Thiết lập cơ chế để tiếp nhận, giải quyết khiếu nại về hoạt động kinh doanh \ndịch vụ quảng cáo trên mạng;\ng) Tuân thủ quy định về minh bạch trong hoạt động quảng cáo trên mạng khi thiết\nlập, vận hành nền tảng số trung gian để cung cấp dịch vụ;\nh) Thực hiện chế độ báo cáo định kỳ hằng năm, báo cáo đột xuất khi có yêu cầu \ncủa cơ quan nhà nước có thẩm quyền.\n6. Người quảng cáo nước ngoài có nhu cầu quảng cáo sản phẩm, hàng hóa, dịch vụ,\ntổ chức, cá nhân của mình qua hình thức quảng cáo xuyên biên giới tại Việt Nam \nthực hiện theo quy định tại Điều 39 của Luật này.\n7. Tổ chức, cá nhân tham gia hoạt động quảng cáo trên mạng phải thực hiện việc \nngăn chặn, gỡ bỏ quảng cáo vi phạm chậm nhất 24 giờ kể từ khi có yêu cầu của cơ\nquan nhà nước có thẩm quyền. Trường hợp không thực hiện theo yêu cầu, cơ quan \nnhà nước có thẩm quyền triển khai các biện pháp kỹ thuật ngăn chặn các vi phạm \npháp luật về quảng cáo và thực hiện biện pháp xử lý theo quy định của pháp \nluật. Doanh nghiệp viễn thông, doanh nghiệp cung cấp dịch vụ Internet có trách \nnhiệm ngăn chặn quảng cáo vi phạm theo yêu cầu của cơ quan nhà nước có thẩm \nquyền.\n8. Chính phủ quy định chi tiết Điều này.\"\n\n**4. Quy định chi tiết về quảng cáo không ở vùng cố định, nền tảng số trung \ngian, gỡ bỏ nội dung trên mạng**\n*Trích nguyên văn các Điều thuộc Mục 2 Chương III Nghị định số 342/2025/NĐ-CP* \n[12-20]:\n\n\"**Điều 17. Quảng cáo không ở vùng cố định**\n1. Quảng cáo không ở vùng cố định là quảng cáo hiển thị tại vị trí, thời điểm \nkhông cố định trên giao diện dịch vụ trực tuyến, che khuất toàn bộ hoặc một \nphần nội dung chính và làm gián đoạn việc tiếp cận thông tin của người sử dụng.\n2. Tính năng, biểu tượng để tắt quảng cáo phải bảo đảm việc quảng cáo được tắt \nchỉ với một lần tương tác; không có biểu tượng tắt quảng cáo giả hoặc biểu \ntượng tắt quảng cáo khó phân biệt, khó xác định.\n3. Không có thời gian chờ tắt quảng cáo đối với quảng cáo dưới dạng hình ảnh \ntĩnh; thời gian chờ tắt quảng cáo tối đa là 05 giây đối với quảng cáo dưới dạng\nchuỗi hình ảnh chuyển động, video.\n4. Phải bố trí biểu tượng và hướng dẫn quy trình để người sử dụng thông báo nội\ndung quảng cáo vi phạm pháp luật và lựa chọn từ chối, tắt hoặc không tiếp tục \nxem quảng cáo không phù hợp. Báo cáo quảng cáo vi phạm pháp luật phải được tiếp\nnhận, xử lý kịp thời và thông tin kết quả cho người sử dụng theo quy định của \npháp luật.\"\n\n\"**Điều 18. Ngăn chặn, gỡ bỏ quảng cáo vi phạm pháp luật trên mạng**\n1. Các bộ, ngành, địa phương rà quét, phát hiện, kiểm tra, xử lý, yêu cầu ngăn \nchặn, gỡ bỏ quảng cáo vi phạm pháp luật trong phạm vi chức năng, nhiệm vụ, \nquyền hạn của mình.\nTrong trường hợp pháp luật chuyên ngành chưa có quy định hoặc các bộ, ngành, \nđịa phương không xác định được danh tính chủ thể đăng phát quảng cáo vi phạm \npháp luật để xử lý và yêu cầu ngăn chặn, gỡ bỏ, Bộ Văn hóa, Thể thao và Du lịch\nlà cơ quan chủ trì tiếp nhận thông báo quảng cáo vi phạm pháp luật từ các bộ, \nngành, địa phương và là đầu mối liên hệ, gửi yêu cầu ngăn chặn, gỡ bỏ tới tổ \nchức, doanh nghiệp kinh doanh dịch vụ quảng cáo trên mạng tại Việt Nam. Khi gửi\nthông báo tới Bộ Văn hóa, Thể thao và Du lịch, các bộ, ngành, địa phương cung \ncấp kết luận của cơ quan có thẩm quyền về quảng cáo vi phạm pháp luật.\n2. Người quảng cáo, người kinh doanh dịch vụ quảng cáo, người chuyển tải sản \nphẩm quảng cáo, người phát hành quảng cáo khi tham gia hoạt động quảng cáo trên\nmạng có trách nhiệm thực hiện hoặc phối hợp thực hiện việc ngăn chặn, gỡ bỏ \nquảng cáo vi phạm pháp luật chậm nhất là 24 giờ kể từ khi có yêu cầu bằng văn \nbản hoặc qua phương tiện điện tử của Bộ Văn hóa, Thể thao và Du lịch hoặc cơ \nquan có thẩm quyền theo quy định của pháp luật chuyên ngành.\nĐối với các quảng cáo có nội dung xâm phạm an ninh quốc gia Việt Nam, phải ngăn\nchặn, gỡ bỏ kịp thời nhưng không chậm hơn 24 giờ kể từ khi có yêu cầu.\n3. Trường hợp không thực hiện quy định tại khoản 2 Điều này thì Bộ Văn hóa, Thể\nthao và Du lịch và Bộ Công an sẽ triển khai các biện pháp kỹ thuật ngăn chặn \nquảng cáo, dịch vụ vi phạm pháp luật và thực hiện các biện pháp xử lý theo quy \nđịnh pháp luật. Biện pháp ngăn chặn chỉ được gỡ bỏ sau khi quảng cáo vi phạm \npháp luật đã được xử lý theo yêu cầu của Bộ Văn hóa, Thể thao và Du lịch hoặc \ncơ quan có thẩm quyền theo quy định của pháp luật chuyên ngành.\n4. Doanh nghiệp viễn thông, doanh nghiệp cung cấp dịch vụ Internet triển khai \ncác biện pháp kỹ thuật cần thiết để ngăn chặn việc truy cập vào các quảng cáo, \ndịch vụ vi phạm pháp luật chậm nhất là 24 giờ kể từ khi có yêu cầu bằng điện \nthoại, văn bản hoặc qua phương tiện điện tử của Bộ Văn hóa, Thể thao và Du lịch\nvà Bộ Công an.\"\n\n\"**Điều 19. Thông báo thông tin liên hệ, lưu trữ thông tin hồ sơ hoạt động \nquảng cáo; chế độ báo cáo, trách nhiệm khi thiết lập, vận hành nền tảng số \ntrung gian để cung cấp dịch vụ hoạt động quảng cáo trên mạng**\n1. Các tổ chức, doanh nghiệp kinh doanh dịch vụ quảng cáo trên mạng tại Việt \nNam (bao gồm các tổ chức, doanh nghiệp trong nước và các tổ chức, doanh nghiệp \nnước ngoài) thực hiện thủ tục thông báo thông tin liên hệ với Bộ Văn hóa, Thể \nthao và Du lịch trước khi bắt đầu kinh doanh dịch vụ tại Việt Nam theo Mẫu số \n03 tại Phụ lục ban hành kèm theo Nghị định này.\nThông báo gửi bằng một trong các hình thức sau: Nộp trực tiếp, nộp qua dịch vụ \nbưu chính, nộp trực tuyến qua phương tiện điện tử hoặc Cổng dịch vụ công quốc \ngia. Trường hợp nộp qua Cổng dịch vụ công quốc gia, phải có chữ ký số theo quy \nđịnh của pháp luật về giao dịch điện tử. Trong thời hạn 04 ngày làm việc kể từ \nngày nhận được thông báo hợp lệ, Bộ Văn hóa, Thể thao và Du lịch cấp giấy xác \nnhận thông báo. Trường hợp thay đổi thông tin liên hệ, tổ chức, doanh nghiệp \nkinh doanh dịch vụ quảng cáo trên mạng tại Việt Nam thực hiện lại thủ tục thông\nbáo thông tin liên hệ và gửi về Bộ Văn hóa, Thể thao và Du lịch.\n2. Người kinh doanh dịch vụ quảng cáo trên mạng phải lưu trữ đầy đủ và bảo đảm \nkhả năng truy cập thông tin, hồ sơ về hoạt động quảng cáo, bao gồm: Thông tin \nvề tên, địa chỉ, chứng nhận đăng ký kinh doanh hoặc tài liệu pháp lý hợp lệ; \ntên sản phẩm, hàng hóa, dịch vụ được quảng cáo; mẫu sản phẩm quảng cáo; thời \ngian cung cấp dịch vụ quảng cáo; vị trí quảng cáo; các tài liệu theo quy định \nkhi thực hiện hoạt động quảng cáo: Hợp đồng, thỏa thuận, các tài liệu liên quan\nđến sản phẩm quảng cáo.\nThời gian lưu trữ: Trong 03 năm kể từ ngày cuối cùng quảng cáo được hiển thị.\n3. Người kinh doanh dịch vụ quảng cáo trên mạng thực hiện chế độ báo cáo định \nkỳ hằng năm về hoạt động kinh doanh dịch vụ quảng cáo trên mạng tại Việt Nam \ntheo Mẫu số 04 Phụ lục ban hành kèm theo Nghị định này. Báo cáo gửi về Bộ Văn \nhóa, Thể thao và Du lịch chậm nhất vào ngày 25 tháng 11 và báo cáo đột xuất khi\ncó yêu cầu của Bộ Văn hóa, Thể thao và Du lịch. Báo cáo được gửi bằng một trong\ncác hình thức sau: Nộp trực tiếp, nộp qua dịch vụ bưu chính, nộp trực tuyến qua\nphương tiện điện tử hoặc Cổng dịch vụ công quốc gia.\n4. Người kinh doanh dịch vụ quảng cáo khi thiết lập, vận hành nền tảng số trung\ngian để cung cấp dịch vụ cần tuân thủ các quy định về minh bạch trong hoạt động\nquảng cáo trên mạng như sau:\na) Thể hiện thông tin của từng quảng cáo cụ thể bao gồm: Tên, địa chỉ của người\nquảng cáo hoặc tổ chức, cá nhân được ủy quyền mua quảng cáo;\nb) Khi thực hiện quảng cáo qua công cụ tìm kiếm cần có dấu hiệu phân biệt kết \nquả hiển thị được tài trợ và kết quả tìm kiếm thông thường.\n5. Người quảng cáo, người kinh doanh dịch vụ quảng cáo có quyền ưu tiên hợp tác\nvới người chuyển tải sản phẩm quảng cáo trên mạng đã được Bộ Văn hóa, Thể thao \nvà Du lịch hoặc cơ quan có thẩm quyền tập huấn, đào tạo về quy định của pháp \nluật về quảng cáo và quản lý, cung cấp, sử dụng dịch vụ Internet và thông tin \ntrên mạng.\"\n\n**5. Quy định về quảng cáo trên màn hình chuyên quảng cáo CÓ KẾT NỐI MẠNG**\n*Trích nguyên văn Khoản 4 Điều 28 Luật Quảng cáo số 16/2012/QH13 (được bổ sung \ntại khoản 16 Điều 1 Luật số 75/2025/QH15)* [21]:\n\"4. Việc quản lý hoạt động quảng cáo trên màn hình chuyên quảng cáo có kết nối \nmạng được thực hiện theo quy định của Chính phủ.\"\n\n*Trích nguyên văn Điều 20 Nghị định số 342/2025/NĐ-CP (Hướng dẫn cho Luật Quảng\ncáo)* [22-25]:\n\"**Điều 20. Quản lý hoạt động quảng cáo trên màn hình chuyên quảng cáo có kết \nnối mạng**\n1. Quảng cáo trên màn hình chuyên quảng cáo (Màn hình LED - Light Emitting \nDiode, LCD - Liquid crystal display, màn hình đặt trong thang máy và các hình \nthức tương tự) có kết nối mạng phải tuân thủ các quy định của pháp luật về \nquảng cáo, quy định về an ninh mạng và quy định về quản lý, cung cấp, sử dụng \ndịch vụ Internet và thông tin trên mạng.\n2. Trách nhiệm của tổ chức, cá nhân kinh doanh dịch vụ quảng cáo trên màn hình \nchuyên quảng cáo có kết nối mạng:\na) Có giải pháp kỹ thuật để người phát hành quảng cáo, người quảng cáo có thể \nkiểm soát và loại bỏ các sản phẩm quảng cáo vi phạm pháp luật trên hệ thống màn\nhình chuyên quảng cáo có kết nối mạng;\nb) Lưu trữ và cung cấp khi có yêu cầu của cơ quan có thẩm quyền quản lý nhà \nnước về quảng cáo tại địa phương các thông tin sau đây:\nSố lượng sản phẩm quảng cáo.\nTên sản phẩm, hàng hóa, dịch vụ quảng cáo; thời gian, lịch phát quảng cáo.\nTên đơn vị, doanh nghiệp chịu trách nhiệm về sản phẩm quảng cáo.\nc) Ngăn chặn, gỡ bỏ thông tin vi phạm pháp luật theo yêu cầu của Bộ Văn hóa, \nThể thao và Du lịch và các cơ quan chức năng có thẩm quyền theo quy định.\n3. Việc thực hiện quảng cáo bằng các màn hình chuyên quảng cáo có kết nối mạng \nđặt trong thang máy phải bảo đảm không làm ảnh hưởng đến các yêu cầu về an toàn\nthang máy.\n4. Việc lắp đặt và sử dụng các thiết bị có chức năng thu thập dữ liệu trên màn \nhình chuyên quảng cáo có kết nối mạng chỉ được thực hiện nhằm mục đích thống \nkê, phân tích số lượng người xem, hiệu quả tiếp cận của hoạt động quảng cáo và \nkhông được thu thập, sử dụng dữ liệu cá nhân. Việc thu thập, xử lý dữ liệu cá \nnhân phải được sự đồng ý của chủ thể dữ liệu cá nhân và tuân thủ các quy định \ncủa pháp luật về bảo vệ dữ liệu cá nhân và pháp luật về bảo vệ quyền riêng tư.\n5. Hệ thống màn hình chuyên quảng cáo có kết nối mạng là tập hợp từ 02 màn hình\nchuyên quảng cáo có kết nối mạng trở lên được quản lý bởi cùng một tổ chức, cá \nnhân và có khả năng cập nhật nội dung quảng cáo từ xa thông qua kết nối mạng. \nHệ thống màn hình chuyên quảng có kết nối mạng phải bảo đảm khả năng ghi nhận \nlịch sử hiển thị, thời gian và nội dung quảng cáo để phục vụ công tác thanh \ntra, kiểm tra và tuân thủ các quy định về an toàn thông tin mạng.\n6. Thẩm quyền quản lý hoạt động quảng cáo trên hệ thống màn hình chuyên quảng \ncáo và màn hình điện tử chuyên quảng cáo có kết nối mạng:\na) Ủy ban nhân dân cấp tỉnh có trách nhiệm tiếp nhận thông tin, quản lý đối với\nmàn hình chuyên quảng cáo và màn hình điện tử chuyên quảng cáo có kết nối mạng \ntrên địa bàn;\nb) Bộ Văn hóa, Thể thao và Du lịch có trách nhiệm tiếp nhận thông tin, quản lý \nđối với hệ thống màn hình chuyên quảng cáo có kết nối mạng đặt trên địa bàn 02 \ntỉnh, thành phố trở lên.\"\n\nConversation: 8090ff64-55ce-4d1b-a033-e37fc1200605 (turn 1)\n",
  "ad-compliance-vn": "# RULE: Tuân thủ luật quảng cáo Việt Nam (mọi kênh truyền thông)\n\n> RULE BẮT BUỘC — áp cho MỌI nội dung quảng cáo GWT phát ra, gồm 5 kênh:\n> (1) viết nội dung (bài/social/web) · (2) kịch bản video · (3) phát ngôn trên\n> camera của nhân sự (vd GĐ kỹ thuật) · (4) telesales gọi điện · (5) nhắn tin\n> cho khách (SMS/Zalo).\n> Khi rule này mâu thuẫn với \"style ref\" → **rule thắng** (tuân thủ luật ưu tiên).\n>\n> ⚠️ KHÔNG phải tư vấn pháp lý. Đối chiếu lại với notebook luật của GWT + bộ phận\n> pháp lý trước khi phát hành.\n>\n> **Trạng thái: v2 (2026-06-29)** — đã trích dẫn điều/khoản từ notebook luật GWT\n> (`fa72c143…`, xem bản trích nguyên văn `rules/_adlaw-from-notebook.md`).\n> Căn cứ chính: **Luật Quảng cáo 16/2012/QH13** + **Luật sửa đổi 75/2025/QH15**\n> (hiệu lực 01/01/2026) + **Nghị định 342/2025/NĐ-CP** (hướng dẫn) + Thông tư\n> 10/2013/TT-BVHTTDL (& 12/2026/TT-BVHTTDL từ 05/07/2026).\n>\n> ⚠️ **3 khoảng trống — notebook chưa có căn cứ, cần tra nguồn riêng:**\n> 1. **Telesales (gọi điện):** notebook KHÔNG chứa NĐ 91/2020/NĐ-CP. Luật QC chỉ\n>    điều chỉnh **tin nhắn/thư điện tử** (Điều 24), KHÔNG có điều khoản về cuộc\n>    gọi quảng cáo. Phần D-(4) dưới đây dựa NĐ 91/2020 (ngoài notebook) — pháp lý\n>    xác nhận lại.\n> 2. **Nhãn nhận diện `[QC]`** trên tin nhắn: notebook không đề cập (do NĐ 91/2020\n>    quy định, ngoài notebook).\n> 3. **Mức xử phạt cụ thể** (NĐ 38/2021): notebook không có. Chỉ có nguyên tắc\n>    \"Chính phủ quy định mức xử phạt\" (khoản 4 Điều 11 Luật 16/2012).\n\n---\n\n## A. CẤM TUYỆT ĐỐI (hard NO — không được xuất hiện trong nội dung/kịch bản)\n\n1. **Sai sự thật / gây nhầm lẫn** về số lượng, chất lượng, giá, công dụng, kiểu\n   dáng, nhãn hiệu, xuất xứ, chủng loại, thời hạn bảo hành của sản phẩm đã đăng\n   ký/công bố.\n   → *Căn cứ: khoản 9 Điều 8 Luật 16/2012/QH13.*\n2. **So sánh** sản phẩm GWT với sản phẩm **cùng loại** của tổ chức/cá nhân khác\n   **mà KHÔNG có tài liệu hợp pháp chứng minh**. → Tránh \"tốt hơn máy X\", \"vượt\n   trội hãng Y\" trừ khi có tài liệu.\n   → *Căn cứ: khoản 10 Điều 8 (sửa đổi tại điểm b khoản 4 Điều 1 Luật 75/2025).\n   Lưu ý điểm mới: luật 2025 không cấm so sánh tuyệt đối nữa, mà cấm so sánh\n   \"không có tài liệu hợp pháp chứng minh\".*\n3. **Từ tuyệt đối** \"nhất\", \"duy nhất\", \"tốt nhất\", \"số một\" (hoặc nghĩa tương\n   tự) **khi không có tài liệu hợp pháp chứng minh** theo quy định Bộ VHTTDL.\n   → *Căn cứ: khoản 11 Điều 8 Luật 16/2012/QH13. Điều kiện dùng: xem mục G.*\n4. **Quảng cáo như thuốc / chữa bệnh / có tác dụng y khoa:** máy lọc nước KHÔNG\n   phải thuốc/thiết bị y tế. CẤM nói/ngụ ý sản phẩm \"chữa\", \"phòng ngừa\", \"điều\n   trị\", \"thay thuốc\" với bệnh (ung thư, sỏi thận, tiểu đường…) hoặc cam kết\n   hiệu quả y khoa.\n   → *Căn cứ (suy ra từ nguyên tắc chung — nguồn KHÔNG có điều khoản riêng cho\n   máy lọc nước): khoản 9 Điều 8 + khoản 1 Điều 19 (sửa đổi tại khoản 11 Điều 1\n   Luật 75/2025): \"Nội dung quảng cáo phải trung thực, chính xác, rõ ràng; không\n   gây hiểu nhầm về tính năng, chất lượng, công dụng, tác dụng\". Tham chiếu tinh\n   thần: NĐ 342/2025 buộc thực phẩm BVSK ghi \"Thực phẩm này không phải là thuốc\n   và không có tác dụng thay thế thuốc chữa bệnh\"; mỹ phẩm \"không được gây hiểu\n   nhầm là thuốc\" — máy lọc nước không thuộc các nhóm này nên KHÔNG có cụm bắt\n   buộc, nhưng nguyên tắc \"không gây hiểu nhầm là thuốc\" vẫn phải tuân.*\n5. **Lợi dụng nỗi sợ bệnh tật** để hù doạ (\"không dùng sẽ bị bệnh…\") — gây hiểu\n   nhầm về công dụng/tác dụng.\n   → *Căn cứ: khoản 1 Điều 19 (sửa đổi tại khoản 11 Điều 1 Luật 75/2025).*\n6. Quảng cáo thiếu căn cứ về \"nước ion kiềm/khoáng/điện giải tốt cho sức khỏe\"\n   nếu không có nghiên cứu/chứng nhận hợp pháp → gây hiểu nhầm về công dụng.\n   → *Căn cứ: khoản 9 Điều 8 + khoản 1 Điều 19.*\n7. Dùng kết quả nghiên cứu, chứng nhận, lời chuyên gia/bác sĩ **chưa được phép**\n   hoặc bịa → sai sự thật/gây nhầm lẫn (khoản 9 Điều 8).\n\n## B. BẮT BUỘC (must — phải có/đảm bảo)\n\n1. **Nội dung phải trung thực, chính xác, rõ ràng; không gây hiểu nhầm** về tính\n   năng, chất lượng, công dụng, tác dụng.\n   → *Căn cứ: khoản 1 Điều 19 (sửa đổi tại khoản 11 Điều 1 Luật 75/2025).*\n2. **Nhận diện rõ là quảng cáo** — phải có dấu hiệu (chữ số/chữ viết/ký hiệu/\n   hình ảnh/âm thanh) phân biệt nội dung quảng cáo với nội dung không phải quảng\n   cáo. (Áp riêng cho kênh mạng/MXH — xem mục E.)\n   → *Căn cứ: điểm a & đ khoản 2 Điều 23 (sửa đổi tại khoản 13 Điều 1 Luật\n   75/2025).*\n3. Mọi **số liệu/tuyên bố công dụng** (vd \"lọc X theo tiêu chuẩn Y\") phải **khớp\n   data thật từ Supabase** + có cơ sở chứng nhận; KHÔNG tự bịa số. Thông tin sản\n   phẩm (tên máy, mã nội bộ, bảo hành, chu kỳ thay lõi, số lượng lõi) lấy từ Supabase\n   qua `scripts/sql/marketing_kit_products.sql`. ⚠️ **Giá đã bị xoá khỏi DB, không còn\n   nguồn: KHÔNG nêu giá trong bất kỳ kênh nào.**\n   ✅ **NGOẠI LỆ — series chuyên gia viết tay** (POU khối 4, POE chuyên gia) **được nêu\n   giá**, với điều kiện GWT chốt số trước khi quay + khớp báo giá chính thức. Xem\n   `rules/claim-can-chung-nhan.md` **mục 2b**. Ngoại lệ này ⛔ không áp cho nội dung do\n   skill sinh (caption/social).\n   ⛔ **KHÔNG nêu TÊN/MÃ lõi lọc** (`LX-CFNC-001-G`, \"lõi NF700\"...) ở bất kỳ kênh nào —\n   chỉ nói \"lõi\" chung chung kèm chu kỳ thay / số lượng lõi. Xem\n   `rules/claim-can-chung-nhan.md` mục 1b.\n   → *Căn cứ: khoản 9 Điều 8 (cấm sai về số lượng/chất lượng/giá/công dụng/bảo\n   hành đã công bố).*\n4. Nếu dùng **người có ảnh hưởng/influencer/KOL** hoặc **nhân sự phát ngôn**:\n   xem mục E-(3). Người đó phải đã thực sự dùng/hiểu sản phẩm mới được giới thiệu.\n   → *Căn cứ: khoản 3 Điều 15a (bổ sung tại khoản 9 Điều 1 Luật 75/2025).*\n\n## C. RIÊNG cho máy lọc nước (rủi ro hay gặp)\n\n- **Được nói:** công nghệ lọc, số cấp lọc, loại bỏ cặn/clo/kim loại nặng **đúng\n  theo chứng nhận sản phẩm**; tiện lợi, tiết kiệm, bảo hành, chu kỳ thay lõi.\n- **KHÔNG được nói:** \"uống vào khỏe ra\", \"chữa bệnh\", \"thay thuốc\", \"nước chữa\n  lành\", hay cam kết hiệu quả sức khỏe không có chứng nhận (mục A-4,5,6).\n- Thay vì \"tốt cho sức khỏe\" (mơ hồ) → claim cụ thể, kiểm chứng được: **\"loại bỏ\n  X theo tiêu chuẩn Y\"** (nếu Supabase/chứng nhận có).\n\n## D. TỪ NGỮ — danh sách rà nhanh\n\n| Loại | Ví dụ | Xử lý | Căn cứ |\n|---|---|---|---|\n| Tuyệt đối | số 1, tốt nhất, duy nhất, nhất | Bỏ, trừ khi có tài liệu hợp pháp + ghi tên tài liệu (mục G) | K11 Đ8 |\n| Y khoa | chữa, trị, phòng bệnh, kháng, miễn dịch | Bỏ hoàn toàn | K9 Đ8 + K1 Đ19 |\n| So sánh | hơn hãng X, vượt trội đối thủ | Bỏ, trừ khi có tài liệu chứng minh | K10 Đ8 (sửa 2025) |\n| Cam kết tuyệt đối | 100% an toàn, đảm bảo khỏi bệnh | Bỏ / chuyển thành claim kiểm chứng được | K9 Đ8 + K1 Đ19 |\n\n## E. LƯU Ý THEO TỪNG KÊNH (đã gắn căn cứ)\n\n**(1) Viết nội dung (bài/social/web) — kênh mạng:**\n- Không sai sự thật, không gây hiểu nhầm công dụng (K9 Đ8 + K1 Đ19).\n- **Phải có dấu hiệu nhận diện là quảng cáo** để phân biệt với nội dung thường;\n  nếu đăng trên MXH dưới tài khoản cá nhân thì phải có dấu hiệu phân biệt nội\n  dung quảng cáo/được tài trợ. (điểm a & đ khoản 2 Điều 23, sửa 2025)\n- Quảng cáo qua công cụ tìm kiếm: phân biệt kết quả được tài trợ với kết quả\n  thường (điểm b khoản 4 Điều 19 NĐ 342/2025).\n- Tránh từ tuyệt đối & y khoa (mục D).\n\n**(2) Kịch bản / video:**\n- Như (1) + phụ đề/hình ảnh minh hoạ không gây hiểu nhầm về tính năng/công dụng\n  (K1 Đ19); nội dung nhận diện được là quảng cáo (K2 Đ23).\n- Tiếng Việt trong sản phẩm quảng cáo phải rõ ràng, dễ hiểu, chính xác (khoản 1a\n  Điều 18, bổ sung tại khoản 10 Điều 1 Luật 75/2025).\n\n**(3) Phát ngôn trên camera của nhân sự (vd GĐ kỹ thuật) / KOL — \"người chuyển\ntải sản phẩm quảng cáo\" & \"người có ảnh hưởng\":**\n- Mọi tuyên bố về **công dụng/hiệu quả** phải có căn cứ (chứng nhận/data\n  Supabase); GĐ kỹ thuật nói về **thông số/khả năng lọc** phải đúng chứng nhận;\n  **KHÔNG** hứa hiệu quả sức khỏe/chữa bệnh, **KHÔNG** \"tốt nhất/số 1\" thiếu căn cứ.\n- Người nói **phải đã thực sự dùng hoặc hiểu rõ sản phẩm** — *\"trường hợp chưa sử\n  dụng hoặc chưa hiểu rõ về sản phẩm… thì không được giới thiệu\"* (điểm a khoản 3\n  Điều 15a). Phải **xác minh độ tin cậy** của bên quảng cáo + **kiểm tra tài\n  liệu** liên quan.\n- Phải **thông báo việc quảng cáo ngay trước và trong khi** thực hiện (điểm b\n  khoản 3 Điều 15a) — vd nói rõ đây là nội dung quảng cáo/được tài trợ.\n- Người chuyển tải **chịu trách nhiệm trước pháp luật** nếu nội dung không bảo\n  đảm yêu cầu Điều 19 (điểm c khoản 2 Điều 15a).\n- → *Căn cứ: Điều 15a (bổ sung tại khoản 9 Điều 1 Luật 75/2025).*\n\n**(4) Telesales (gọi điện):**\n- ⚠️ **Notebook luật GWT KHÔNG có căn cứ cho cuộc gọi quảng cáo** (không chứa\n  NĐ 91/2020/NĐ-CP). Luật Quảng cáo chỉ điều chỉnh tin nhắn/email (Điều 24).\n- Khung tuân thủ dưới đây dựa **NĐ 91/2020 (ngoài notebook) — pháp lý xác nhận**:\n  chỉ gọi khi khách **đã đồng ý trước (opt-in)**; **xưng danh GWT** + mục đích;\n  gọi trong **khung giờ cho phép**; cho khách **từ chối** và KHÔNG gọi lại khi đã\n  từ chối. Nội dung nói vẫn tuân mục A–D.\n- 📌 *Việc cần làm: bổ sung NĐ 91/2020 vào notebook hoặc chạy truy vấn nguồn\n  riêng để trích điều khoản chính xác.*\n\n**(5) Nhắn tin cho khách (SMS/email; Zalo suy luận tương tự):**\n- **Chỉ gửi khi người nhận đã đồng ý trước (opt-in).**\n  → *điểm a khoản 1 Điều 24 Luật 16/2012: \"chỉ được phép gửi tin nhắn và thư điện\n  tử quảng cáo khi có sự đồng ý trước của người nhận\".*\n- **Khung giờ + tần suất:** chỉ gửi tin nhắn quảng cáo **07h–22h**; **không quá 3\n  tin nhắn / 1 số điện thoại** (và không quá 3 email / 1 địa chỉ) **trong 24 giờ**,\n  trừ khi có thỏa thuận khác.\n  → *điểm b khoản 1 Điều 24.*\n- **Opt-out:** bảo đảm người nhận **từ chối được**; **chấm dứt ngay** khi bị từ\n  chối; **không thu phí** với thông báo từ chối.\n  → *điểm c khoản 1 Điều 24.*\n- ⚠️ **Nhãn `[QC]`:** notebook không đề cập (quy định ở NĐ 91/2020 — ngoài\n  notebook). Khuyến nghị vẫn gắn nhãn nhận diện quảng cáo; pháp lý xác nhận hình\n  thức nhãn theo NĐ 91/2020.\n\n## F. CHECKLIST tự kiểm (chạy trước khi phát mọi kênh)\n\n- [ ] Mọi công dụng/số liệu đều khớp Supabase + có cơ sở? *(K9 Đ8, K1 Đ19)*\n- [ ] Không có từ tuyệt đối / y khoa / so sánh thiếu căn cứ? *(K9/K10/K11 Đ8)*\n- [ ] Không định vị sản phẩm như thuốc/chữa bệnh? *(K1 Đ19)*\n- [ ] Nhận diện được là quảng cáo (kênh mạng/MXH)? *(K2 Đ23)*\n- [ ] Nếu có KOL / nhân sự phát ngôn: đã thực sự dùng/hiểu SP; tuyên bố có căn\n      cứ; có thông báo là quảng cáo? *(Đ15a)*\n- [ ] (Tin nhắn/email) Khách đã opt-in? Gửi 07h–22h, ≤3 tin/24h? Có cách từ\n      chối? *(Đ24)*\n- [ ] (Telesales) Khách đã đồng ý? Có xưng danh + cách từ chối? *(NĐ 91/2020 —\n      cần xác nhận, ngoài notebook)*\n- [ ] Có điểm nào nghi ngờ → đánh dấu để người duyệt + pháp lý xem.\n\n> Quy trình: soạn nội dung (theo kênh) → tự rà checklist F → gắn cảnh báo nếu có\n> điểm rủi ro → người duyệt + pháp lý quyết định cuối.\n\n## G. PHỤ LỤC — dùng \"nhất / số một / tốt nhất\" hợp pháp (nếu thật sự cần)\n\nChỉ được dùng khi **có tài liệu hợp pháp chứng minh** và **ghi rõ tên tài liệu\ntrên sản phẩm quảng cáo**.\n\n- **Hiện hành (đến 04/07/2026): Điều 2 Thông tư 10/2013/TT-BVHTTDL** — tài liệu\n  hợp pháp gồm: (a) kết quả khảo sát thị trường của tổ chức có chức năng nghiên\n  cứu thị trường; (b) giấy chứng nhận tại cuộc thi/triển lãm quy mô khu vực/toàn\n  quốc. **Thời hạn dùng: 01 năm** kể từ ngày cấp/nhận kết quả. Phải thể hiện đầy\n  đủ, rõ ràng tên tài liệu trên sản phẩm quảng cáo.\n- **Từ 05/07/2026: Điều 3 Thông tư 12/2026/TT-BVHTTDL** (thay TT 10/2013) — tài\n  liệu tương tự; **thời hạn dùng theo thời hạn của giấy chứng nhận/kết quả khảo\n  sát**; phải ghi rõ tên tài liệu, số/ký hiệu, thời gian; tài liệu phải độc lập,\n  khách quan, trung thực, không gây nhầm lẫn.\n\n→ Thực tế GWT hiện chưa có tài liệu loại này → **mặc định KHÔNG dùng** từ tuyệt đối.\n\n---\n\n> Nguồn trích nguyên văn đầy đủ: `rules/_adlaw-from-notebook.md` (tự sinh từ\n> notebook `fa72c143…` bằng `scripts/extract-ad-law.ps1`). File này là bản RULE\n> đã tinh gọn để áp dụng; khi luật đổi → chạy lại script & cập nhật.\n",
  "claim-can-chung-nhan": "# ⚠️ Claim cần chứng nhận + nguyên tắc phát ngôn (master-agent đọc TRƯỚC khi duyệt)\n\n> Ràng buộc BẮT BUỘC khi duyệt / đưa vào sản xuất bất kỳ\n> kịch bản hay caption nào. Cùng cấp với `rules/ad-compliance-vn.md`: rule QC thắng style.\n> Nguồn sự thật số liệu: Supabase project `qynpywysgltspmgnhhga`, đọc qua\n> `scripts/sql/marketing_kit_products.sql` (`catalog_item` + `product_warranty` +\n> `product_variant` + `v_machine_filter` + `product_bundle`).\n> Cập nhật: 2026-07-17.\n>\n> 📌 File này TÁCH RA từ `drafts/scripts/_WARNINGS.md` (2026-07-17, vấn đề W7-1): phần\n> ràng buộc pháp lý bền vững chuyển vào `rules/` để **theo repo tới mọi máy** (thư mục\n> `drafts/` bị gitignore nên nội dung này từng chỉ tồn tại local). Trạng thái nháp từng\n> file (gen lại file nào, thiếu data gì) vẫn ở `drafts/scripts/_WARNINGS.md`.\n>\n> 🔑 Mã dùng trong file này là **mã nội bộ** (`CTS10NB`/`CTS10NW`, `CTS20NG`, `CTD50NG`,\n> `GTUN-8600HP-G` = USH10 cũ, `WH15A`). KHÔNG dùng mã model cũ.\n\n---\n\n## 0. Nguyên tắc cho master-agent\n- **Số liệu phải khớp Supabase**; khi data nội bộ mâu thuẫn → KHÔNG tự chọn, phải\n  để người/pháp lý chốt.\n- **Sau migrate masterdata (2026-07-17)**: số liệu được phép nêu chỉ còn **bảo hành +\n  lõi lọc + chu kỳ thay**. **Giá, mô tả bán, công dụng KHÔNG còn nguồn** ⇒ không nêu,\n  không bịa.\n- **Claim cần chứng nhận** (diệt khuẩn %, TÜV, QCVN, \"độc quyền\", \"duy nhất\") chỉ\n  được phát khi có giấy tờ hợp lệ kèm (xem mục 1).\n\n---\n\n## 1. Claim cần CHỨNG NHẬN trước khi phát công khai\n> Hiện đã được GIỮ NGOÀI voice-over/overlay để an toàn. Muốn dùng (nhất là các\n> điểm bán mạnh) → pháp lý/QA xác nhận giấy tờ còn hiệu lực rồi mới thêm vào.\n\n| Mã nội bộ | Claim | Ghi chú | Trạng thái |\n|---|---|---|---|\n| CTS10NB / CTS10NW | \"All-in-one **duy nhất** tại VN\" | Từ tuyệt đối (rule A.3/D) – cần tài liệu | Đã bỏ khỏi VO/overlay |\n| CTS10NB / CTS10NW | \"UVC diệt **99,999%** vi khuẩn\" | Claim diệt khuẩn cần chứng nhận (B.2) | Đã bỏ % (chỉ nói \"có đèn UVC\") |\n| CTS10NB / CTS10NW | \"Đạt **QCVN 6-1:2010/BYT**\" | Cần giấy hợp quy còn hiệu lực | Nêu ở mức cần xác nhận |\n| CTD50NG | \"Khử trùng UV **99,999%**\" | Như trên | Đã bỏ % khỏi VO |\n| GTUN-8600HP-G | \"Chứng nhận **TÜV Rheinland** (Đức)\" | **Điểm bán mạnh** – dùng được nếu có giấy | Đã giữ ngoài VO, chờ xác nhận |\n| GTUN-8600HP-G | \"UVC Flow diệt **99,999%**\" | Cần chứng nhận | Đã bỏ % khỏi VO |\n| GTUN-8600HP-G | \"G+ Mineral / thiết kế lõi **độc quyền**\" | \"Độc quyền\" nên có cơ sở (sáng chế) | Hạn chế dùng |\n| WH15A | \"làm mềm nước / giảm cặn vôi\" mức độ cụ thể | Tránh phóng đại; có cơ sở kỹ thuật khi nêu số | Nêu ở mức cơ chế |\n\n---\n\n## 1b. ⛔ CẤM nêu TÊN / MÃ LÕI LỌC trong mọi nội dung marketing\n> Người dùng chốt 2026-07-18. Áp cho **mọi** nội dung xuất bản: caption, kịch bản\n> voice-over, text overlay, bài web/SEO, telesales, tin nhắn.\n\n**CẤM tuyệt đối:**\n- Mã lõi đầy đủ: `LX-CFNC-001-G`, `LX-CFNC-002-G`, `LX-NF700-003-G`, `LX-PCFB-003-G`\n  và mọi mã cùng dạng.\n- Cách gọi tắt/rút gọn: \"lõi NF700\", \"lõi CFNC\", \"lõi PCFB\"...\n\n**VẪN ĐƯỢC dùng bình thường:**\n- Nói **\"lõi\" / \"lõi lọc\"** chung chung, không kèm tên hay mã.\n- **Chu kỳ thay** — giữ nguyên, KHÔNG bị cấm (vd \"12 đến 24 tháng\", \"24 đến 48 tháng\").\n- **Số lượng lõi** (vd \"một lõi\", \"hai lõi\").\n\n**Lý do:** mã lõi là thông tin kỹ thuật nội bộ, không có giá trị với người đọc social,\nvà làm caption nặng tính catalog.\n\n⚠️ Cấm **ĐƯA TÊN VÀO NỘI DUNG**, KHÔNG cấm đọc dữ liệu. Skill vẫn query trường\n`loi_loc` từ Supabase như cũ để lấy chu kỳ thay và số lượng lõi.\n\n---\n\n## 2. Nguyên tắc cách diễn đạt (để master-agent nhất quán khi sửa)\n- **Giá:** nay không còn nguồn trong DB ⇒ kịch bản **không nêu giá dưới bất kỳ dạng nào**\n  (kể cả mức \"tiết kiệm / trọn gói rẻ hơn\"), cho tới khi GWT chốt lại nguồn giá.\n  **→ Có NGOẠI LỆ, xem mục 2b.**\n\n### 2b. ✅ NGOẠI LỆ — SERIES CHUYÊN GIA được nêu giá\n> GWT chốt **2026-07-24**. Ngoại lệ hẹp, có điều kiện — ⛔ **không suy rộng** sang loại\n> nội dung khác.\n\n**Vì sao có ngoại lệ:** lệnh cấm ở mục 2 là **rule NGUỒN DỮ LIỆU** (\"giá đã bị xoá khỏi\nDB, không còn nguồn\"), **không phải lệnh cấm pháp lý** — căn cứ khoản 9 Điều 8 Luật QC chỉ\ncấm nêu giá **SAI** so với công bố, không cấm nêu giá. Khi có nguồn giá đáng tin và được\nGWT xác nhận, lý do cấm không còn.\n\n| | Nội dung do SKILL sinh<br>(caption, social, script ngắn) | SERIES CHUYÊN GIA<br>(viết tay, review nhiều vòng) |\n|---|---|---|\n| Nguồn giá | ❌ không có (DB đã xoá trường) | ✅ fact-sheet SP + GWT chốt trước khi quay |\n| Nêu giá | ⛔ **CẤM** | ✅ **ĐƯỢC** |\n\n**Điều kiện bắt buộc khi series chuyên gia nêu giá:**\n1. Con số phải **GWT chốt trước khi quay** — không đọc số \"khoảng chừng\" từ tài liệu còn\n   mâu thuẫn. Chỗ chưa chốt phải gắn ⚠️ chặn quay.\n2. Phải **khớp báo giá chính thức** đang áp dụng (khoản 9 Điều 8: sai lệch giá đã công bố\n   = vi phạm).\n3. Nêu giá theo hướng **tổng chi phí sở hữu** (giá máy + vật tư + công), ⛔ không dùng giá\n   làm chiêu thúc ép (\"giảm hôm nay\", \"chỉ còn X suất\").\n\n**Vì sao series chuyên gia CẦN nêu giá:** trục niềm tin của series là **minh bạch chi phí\n5 năm** — anh Như hứa trên sóng ở tập 14, trả nợ ở tập 17 và tập 23 (trọn một tập là bảng\nchi phí). Gỡ giá là gãy lời hứa xuyên 16 tập và làm tập 23 mất lý do tồn tại.\n\n**Áp cho:** `drafts/scripts/POU-KHOI4-*` · `drafts/scripts/POE-chuyengia-*` và các series\nchuyên gia viết tay sau này. ⛔ **KHÔNG áp cho** `caption-from-image-v1`, `write_script`,\nhay bất kỳ nội dung nào do skill sinh tự động.\n- **Mọi mã:** 8 khoáng / lọc kim loại nặng / UV chỉ mô tả **công năng kỹ thuật**,\n  KHÔNG định vị y khoa (\"tốt cho sức khỏe / phòng/chữa bệnh\") và KHÔNG hù doạ bệnh\n  tật (rule A.4, A.5, C).\n- Không dùng từ tuyệt đối (\"số 1/tốt nhất/duy nhất\") và không so sánh đối thủ.\n\n---\n\n> Trạng thái nháp từng file, tình trạng thiếu data theo mã, danh sách combo POE chưa gen:\n> xem `drafts/scripts/_WARNINGS.md` (local, không vào git).\n",
  "nguon-dan-chung": "# RULE: CHUẨN NGUỒN DẪN CHỨNG — mọi số liệu và câu chuyện đưa lên kênh\n\n> RULE BẮT BUỘC cho **mọi nội dung** GWT phát ra: video, caption, bài viết, kịch bản,\n> telesales, tin nhắn inbox, tài liệu bán hàng, tài liệu đào tạo.\n> Áp CÙNG với `rules/ad-compliance-vn.md` (luật thắng mọi rule khác),\n> `rules/video-ads-general.md` và `rules/video-loc-tong.md`.\n> Nguồn quyết định: GWT — 2026-07-22.\n\n---\n\n## 0. Vì sao có rule này — một ca thật trong chính kho tài liệu của mình\n\nRà kho tài liệu nội bộ ngày 2026-07-22 phát hiện: file\n`Thông tin sản phẩm/Tổng hợp nhiều sản phẩm/[MKT] Content Research.md`, mục\n**\"Nước cứng mềm\"**, chứa bảng độ cứng theo tỉnh **do AI sinh ra** (ghi nguồn\n\"Perplexity\"). Đối chiếu với **số đo thật**:\n\n| Khu vực | File research nói | Số thật (công ty cấp nước / GE đo) | Chênh |\n|---|---|---|---|\n| **Đà Nẵng** | \"150–200 mg/L, thuộc loại nước cứng\" | **10–30 ppm** (DAWACO) · catalogue GE ghi **30** | **sai 5–7 lần** |\n| **Huế** | \"200–250 mg/L, rất cứng\" | **3,2–44 ppm** (HueWACO) | **sai ~6 lần** |\n| **Hà Nội** | \"80–120 mg/L, cứng vừa phải\" | 71–176 tuỳ nhà máy; Yên Phụ tới **235** | thấp hơn thực tế |\n\nNếu một video đã lên sóng nói *\"Đà Nẵng nước cứng 150–200\"*, thì:\n- **Sai sự thật** — vi phạm K9 Đ8 Luật Quảng cáo;\n- **Tự mâu thuẫn với chính catalogue GE** (ghi Đà Nẵng 30);\n- **Mất uy tín tức thì** với đúng tệp khách hàng ta đang nhắm — người có kiến thức,\n  tra được số của nhà máy cấp nước tỉnh mình trong 2 phút.\n\n> 📌 **Bài học:** nguy hiểm nhất **không phải** số liệu đối thủ tung ra. Là **số liệu\n> sai nằm sẵn trong tài liệu nội bộ của chính mình**, và người viết kịch bản tin nó vì\n> nó nằm trong thư mục công ty.\n\n---\n\n## 1. PHÂN HẠNG NGUỒN — 4 hạng\n\nMọi con số, mốc thời gian, tên riêng, kết luận khoa học đưa lên kênh **phải được gắn\nmột hạng nguồn** trước khi duyệt.\n\n### 🟢 HẠNG A — NGUỒN SƠ CẤP. Dùng được, đọc thẳng trên hình.\n\n| Loại | Ví dụ |\n|---|---|\n| Văn bản pháp quy | QCVN 01-1:2024/BYT · Thông tư 52/2024/TT-BYT · Luật Quảng cáo 16/2012 + 75/2025 |\n| Tiêu chuẩn quốc tế bản gốc | NSF/ANSI 42/44/53/61/372 · WQA · EN · TrinkwV · WRMG |\n| Báo cáo tổ chức quốc tế | **WHO — *Nutrients in Drinking Water* (2005)** · EPA · UNICEF · MHLW Nhật · PUB Singapore |\n| Nghiên cứu bình duyệt, có tên tác giả + tạp chí + năm | Smeets, Medema & van Dijk (2009), *Drinking Water Engineering and Science* 2:1–14 · Pieper, Tang & Edwards (2017), *Environmental Science & Technology* |\n| Công bố của chính đơn vị cấp nước | Trang \"chất lượng nước\" của HAWACO, DAWACO, SAWACO… |\n| **Số đo của chính GWT**, có biên bản | Phiếu đo tại nhà khách · báo cáo bảo trì · phiếu kiểm nghiệm phòng thí nghiệm |\n| Tài liệu kỹ thuật của hãng, có bản cứng lưu hồ sơ | Catalogue GE · phiếu chứng nhận vật liệu |\n\n### 🟡 HẠNG B — NGUỒN THỨ CẤP UY TÍN. Dùng được, **nhưng phải truy về hạng A trước khi quay**.\n\nBáo lớn trong nước (Nhân Dân, Tuổi Trẻ, VnExpress, Dân Trí) · báo/tạp chí ngành quốc\ntế (WC&P, WaterWorld) · bảo tàng, thư viện quốc gia · sách của tác giả chuyên ngành.\n\n> **Cách dùng:** báo là **đường dẫn tới nguồn gốc**, không phải nguồn gốc.\n> Ví dụ đúng: báo Nhân Dân đưa tin về nghiên cứu của Viện Y học lao động → **trích tên\n> viện và tên nghiên cứu**, ghi thêm \"thông tin được báo Nhân Dân đưa\".\n> Ví dụ sai: *\"theo báo, asen ở Việt Nam vượt chuẩn 50%\"* — không có ai chịu trách\n> nhiệm cho con số đó.\n\n### 🟠 HẠNG C — CHƯA ĐỦ. Chỉ dùng để **định hướng đi tìm**, ⛔ **không lên hình**.\n\n- **Nội dung do AI sinh ra** (ChatGPT, Perplexity, Claude…) — kể cả khi nằm trong tài\n  liệu nội bộ của công ty.\n- **Podcast, video YouTube, KOL** — kể cả chuyên gia thật như Huberman hay TS. Burkart.\n  *(Podcast là hạng C vì nó là **lời nói**, không phải tài liệu. Nhưng nghiên cứu mà\n  podcast **dẫn tên** thì là hạng A — phải đi tìm đúng nghiên cứu đó.)*\n- **Bình luận diễn đàn, group Facebook, TikTok** — quý để hiểu khách nghĩ gì, ⛔ vô giá\n  trị làm dẫn chứng.\n- **Trang tổng hợp SEO, blog bán hàng, website đối thủ.**\n- **Tài liệu marketing cũ của chính GWT** chưa được rà lại.\n\n### 🔴 HẠNG D — ⛔ CẤM TUYỆT ĐỐI\n\n- Số liệu **không truy được về bất kỳ ai**.\n- Số liệu **tự suy ra bằng phép tính** rồi trình bày như số đo.\n- Số liệu **nhớ mang máng** (\"hình như khoảng…\", \"nghe nói tầm…\").\n- Số liệu **của đối thủ** dùng để so sánh mà không có tài liệu (K10 Đ8).\n\n---\n\n## 2. QUY TẮC TRÊN HÌNH — thẻ nguồn là bắt buộc\n\n1. **Mỗi con số hạng A phải có thẻ nguồn trên overlay.** Chữ nhỏ, góc dưới, hiện cùng\n   lúc với con số. Ghi: **tên cơ quan/tác giả + năm**. Không ghi link.\n2. **Mỗi số đo của GWT phải kèm bối cảnh:**\n   🔒 *\"Số đo tại nhà khách, tại một thời điểm — không phải số trung bình khu vực.\"*\n3. **Khi trích nghiên cứu, phải giữ nguyên mức độ chắc chắn của nó.** Đây là kỹ thuật\n   quan trọng nhất và cũng là hàng rào pháp lý mạnh nhất — học từ Huberman:\n\n   | Nghiên cứu nói | Trên hình phải nói |\n   |---|---|\n   | Association / correlation | **\"mối liên hệ\"**, ⛔ không nói \"gây ra\", \"làm giảm\" |\n   | Case-control, cỡ mẫu nhỏ | **\"một nghiên cứu quy mô nhỏ ghi nhận…\"** |\n   | Animal study | **\"nghiên cứu trên động vật\"** — ⛔ không suy sang người |\n   | Chưa có bằng chứng | **\"chưa có bằng chứng\"**, ⛔ không nói \"không có tác dụng\" |\n\n4. **Số của nước ngoài không được trình bày như số của Việt Nam.** Ngưỡng fluoride của\n   Mỹ, độ cứng của Đức, quy chuẩn EU — mỗi thứ phải kèm chữ **\"ở [nước đó]\"**.\n\n---\n\n## 3. QUY TẮC ĐƠN VỊ — chỗ sai nguy hiểm nhất\n\n⛔ **CẤM đặt cạnh nhau hai con số đo hai đại lượng khác nhau**, dù chúng gần nhau về\nchữ số.\n\n**Ca điển hình đã suýt xảy ra:**\n- GE cam kết **độ cứng < 17 mg/l**, tính theo **CaCO₃**.\n- Huberman nêu **magie nguyên tố 8,3–19,4 mg/L**.\n- **17 và 19,4 nhìn rất gần nhau — nhưng đo hai thứ hoàn toàn khác nhau.** Đặt cạnh\n  nhau, khán giả sẽ hiểu là GE làm mềm nước xuống dưới ngưỡng \"tốt cho tim mạch\".\n\n**Quy tắc:** mọi con số nồng độ phải ghi rõ **đo cái gì** trước khi ghi **bao nhiêu**.\n- ✅ \"độ cứng tổng, tính theo CaCO₃: 210 mg/l\"\n- ❌ \"độ cứng 210\" đặt cạnh \"magie 19,4\"\n\nTương tự: **ppm và mg/l** với độ cứng thì tương đương — nhưng **°dH (Đức)** thì không\n(**1 °dH ≈ 17,8 mg/l CaCO₃**). ⛔ Không đọc phép quy đổi này trên camera.\n\n---\n\n## 4. QUY TRÌNH XÁC MINH — 4 bước, làm TRƯỚC khi quay\n\n```\n① LIỆT KÊ   — rút mọi con số, mốc năm, tên riêng, kết luận khoa học trong kịch bản\n             ra một bảng riêng. Không bỏ sót con số nào, kể cả trong text overlay.\n② GẮN HẠNG  — mỗi dòng gắn A / B / C / D + ghi rõ nguồn cụ thể.\n③ XỬ LÝ     — B: truy về A · C: đi tìm nguồn A, không tìm được thì GỠ · D: GỠ ngay.\n④ LƯU HỒ SƠ — mọi số hạng A phải có bản lưu (PDF/ảnh chụp/phiếu đo) trong hồ sơ,\n             để xuất trình khi bị hỏi (K9, K10, K11 Đ8).\n```\n\n> ⛔ **Không có hồ sơ = không được nói.** Kể cả khi con số đúng.\n> Luật Quảng cáo không hỏi \"có đúng không\", luật hỏi **\"có tài liệu chứng minh không\"**.\n\n---\n\n## 5. KHI HAI NGUỒN MÂU THUẪN\n\n**Không tự chọn nguồn nào có lợi hơn.** Thứ tự xử lý:\n\n1. **Kiểm tra xem chúng có thật sự mâu thuẫn không** — rất nhiều \"mâu thuẫn\" thực ra là\n   **hai câu hỏi khác nhau**. Ví dụ: độ cứng **trung bình theo nhà máy** và độ cứng\n   **đo tại một nhà khách** là hai loại số khác nhau, cả hai đều đúng.\n2. **Nếu khác loại → nói rõ đang trích loại nào.** Đây là cách xử lý đúng, không phải\n   né tránh.\n3. **Nếu thật sự mâu thuẫn → hạng nguồn cao hơn thắng.** Số đo có biên bản thắng số\n   catalogue; catalogue thắng brochure cũ.\n4. **Nếu cùng hạng mà vẫn vênh → GỠ khỏi kịch bản**, ghi vào danh sách chờ GWT chốt.\n   ⛔ **Không lấy trung bình cộng của hai con số vênh nhau.**\n\n**Ca đang mở (2026-07-22):** Yên Phụ — GWT đưa **240–260**, tài liệu nhà máy ghi\n**180–235**. Chưa xác định là cùng loại số hay khác loại → **chưa được quay**.\n\n---\n\n## 6. VỚI CÂU CHUYỆN LỊCH SỬ VÀ CHUYỆN NƯỚC NGOÀI\n\nÁp dụng cho toàn bộ tuyến kể chuyện (`POE-tuyen-cauchuyen-nuoc-v1.md`) và các beat kể\nchuyện trong tập 5, 6, 12.\n\n1. **Người nói không sống qua câu chuyện → không viết dạng sườn ý để tự diễn đạt.**\n   Phải viết **lời kể gần nguyên văn** + **diễn giải để người nói hiểu** + **nguồn đọc\n   thêm**. Lý do: kể sai một dữ kiện lịch sử mất uy tín nhiều hơn là nói hơi giống văn viết.\n2. **Mỗi câu chuyện phải có ít nhất một nguồn hạng A hoặc B**, ghi ở cuối beat.\n3. **Tên người, năm, địa danh, con số phải tra ít nhất 2 nguồn độc lập.**\n   *(Ca thật: mốc phong tước Doulton — tài liệu nội bộ ghi \"1901 Edward VII phong tước\",\n   tra ra là **trộn hai sự kiện**: Victoria phong tước **1887**, Edward VII ban chữ\n   \"Royal\" **1901**, sau khi ông đã mất 4 năm.)*\n4. **Chi tiết không tra được → kể ở mức khái quát, đừng bịa cho tròn.**\n   ✅ *\"một em bé năm tháng tuổi ở phố đó\"* — ❌ bịa tên, bịa số nhà.\n5. ⛔ **Không dùng uy tín cá nhân người nước ngoài để bảo chứng cho sản phẩm GE.**\n   Không đặt tên/hình Huberman, TS. Burkart, hay bất kỳ chuyên gia nào cạnh logo GE.\n   Được trích **nội dung khoa học**; ⛔ không mượn **con người**.\n\n---\n\n## 7. CHECKLIST RÀ NGUỒN — dán vào cuối mọi kịch bản\n\n- [ ] Đã lập **bảng liệt kê toàn bộ con số** trong kịch bản (cả lời thoại và overlay)?\n- [ ] Mỗi con số đã **gắn hạng A/B/C/D** và ghi nguồn cụ thể?\n- [ ] Mọi số **hạng C và D đã bị gỡ** hoặc đã truy được về hạng A?\n- [ ] Mọi số hạng A đã có **bản lưu trong hồ sơ**?\n- [ ] Mỗi con số trên hình có **thẻ nguồn** (tên cơ quan + năm)?\n- [ ] Số đo của GWT có kèm câu **\"đo tại nhà khách, tại một thời điểm\"**?\n- [ ] Đã giữ đúng **mức độ chắc chắn** của nghiên cứu (tương quan ≠ nhân quả)?\n- [ ] Không có **hai đơn vị khác nhau đặt cạnh nhau** (CaCO₃ vs nguyên tố vs °dH)?\n- [ ] Số nước ngoài có ghi rõ **\"ở nước nào\"**?\n- [ ] Câu chuyện lịch sử: có **lời kể gần nguyên văn** + **nguồn đọc thêm**?\n- [ ] Không mượn **tên/hình chuyên gia nước ngoài** để bảo chứng sản phẩm?\n- [ ] Nguồn mâu thuẫn: đã xử lý theo mục 5, **không tự chọn cái có lợi**?\n\n---\n\n## 8. ⛔ DANH SÁCH ĐEN — nguồn đã phát hiện có vấn đề, không dùng lại\n\n| Nguồn | Vấn đề | Trạng thái |\n|---|---|---|\n| `[MKT] Content Research.md` — mục **\"Nước cứng mềm\"** | Bảng độ cứng theo tỉnh **do AI sinh** (ghi nguồn \"Perplexity\"); Đà Nẵng và Huế **sai 5–7 lần** so với công bố của công ty cấp nước | ⛔ **Không dùng bất kỳ con số nào trong mục này.** Cần xoá hoặc gắn cảnh báo tại chỗ |\n| Cùng file — các đoạn về nước cứng **gây sỏi thận, lão hoá da, phá vỡ collagen, gây mụn** | Vừa là claim y khoa (cấm theo `ad-compliance-vn.md`), vừa **không có nguồn**, văn phong AI | ⛔ Cấm dùng dưới mọi hình thức |\n| `Thông tin sản phẩm/Lọc tổng/So sánh…` (bộ file so sánh đối thủ) | Chứa claim sức khoẻ mạnh (*\"clo gây khô da, rụng tóc\"*, *\"hấp thụ THMs\"*) | ⛔ Chỉ dùng **nội bộ/đào tạo sale**, không lên kênh (đã ghi ở `video-loc-tong.md`) |\n| **Catalogue GE** tờ 08 và tờ 10 | Chứa claim *tóc \"dễ rụng\"*, da *\"dễ bị mụn\"*, clo *\"gây ung thư\"*; tờ 02 còn ghi *\"bảo trì trọn đời\"* và *\"bảo hiểm 1 tỷ\"* (gói đã **không gia hạn**) | ⚠️ Catalogue là nguồn **thông số**, ⛔ **không phải nguồn phát ngôn**. Cần sửa catalogue |\n| Bảng \"Độ cứng trung bình\" trong `Kết quả nước tại các công ty cấp nước…` | 3 tỉnh (Bình Phước, Quảng Trị, Ninh Thuận) bị lỗi parse Excel → hiện thành **ngày tháng** | ⚠️ 3 tỉnh này **không có số dùng được** |\n\n---\n\n## 8b. 🎙️ TRANSCRIPT TỰ ĐỘNG (Whisper/auto-caption) = **HẠNG C với MỌI CON SỐ**\n\n> Ca thật, **2026-07-24**, tuyến react: transcript Whisper của một video TikTok ghi\n> *\"3 ppm nghĩa là trong 1 lít có **30mg** chất rắn\"*. Kịch bản react đã viết hẳn một nhịp\n> chê người ta *\"sai đơn vị 10 lần\"*. **Nghe lại bản gốc: người ta nói \"3mg\" — đúng hoàn\n> toàn.** Máy nghe nhầm, không phải người nói sai.\n\n**Quy tắc:**\n- Transcript tự động dùng tốt để **nắm ý, tìm đề tài, dựng bố cục** → hạng B cho *ý*.\n- Nhưng **mọi CON SỐ, ĐƠN VỊ, TÊN RIÊNG, MỐC THỜI GIAN** trong transcript tự động là\n  **hạng C** — ⛔ không lên hình, ⛔ không trích, ⛔ **không lấy làm căn cứ phản biện ai**,\n  cho tới khi **nghe lại đúng đoạn đó trong bản gốc**.\n- Số tiếng Việt hay bị nghe nhầm nhất: **3/30/13**, **15/50**, **mươi/mười**, đơn vị\n  **mg ↔ mg/L ↔ ppm**, và số có dấu thanh (**bảy/bẩy**, **tư/tứ**).\n\n**⚠️ Riêng tuyến REACT thì đây là rule sống còn.** Cả tuyến đứng trên uy tín *\"người này\nbiết nghề\"*. **Bắt lỗi nhầm một người đang nói đúng là tự bắn vào uy tín đó** — và khán\ngiả sẽ mở bản gốc kiểm tra, vì video gốc đang có sẵn hàng trăm nghìn view.\n→ **Bắt buộc: nghe lại đúng giây có con số, trước khi viết bất kỳ câu phản biện nào.**\n→ Nếu không nghe lại được (video đã gỡ, không rõ tiếng): **bỏ nhịp phản biện đó**, react\nvào phần khác. ⛔ Không đoán.\n\n---\n\n## 9. LIÊN KẾT\n\n- Luật quảng cáo: `rules/ad-compliance-vn.md` — **thắng mọi rule khác**\n- Cấu trúc video ads: `rules/video-ads-general.md`\n- Lọc tổng: `rules/video-loc-tong.md` — đặc biệt **mục 1b** (số liệu chốt) và **mục 1d**\n  (thông tin không nói ra)\n- Cách nói của chuyên gia: `style-notes/chuyen-gia.md`\n",
  "video-ads-general": "# RULE: Yêu cầu chung cho VIDEO CHẠY ADS (mọi sản phẩm)\n\n> RULE BẮT BUỘC cho mọi video làm ra để **chạy quảng cáo**. Áp cùng\n> `rules/ad-compliance-vn.md` (luật thắng mọi rule), **`rules/nguon-dan-chung.md`\n> (chuẩn nguồn cho mọi số liệu — bắt buộc)** và — nếu là lọc tổng —\n> `rules/video-loc-tong.md`.\n> Nguồn: yêu cầu GWT 2026-07-21 · bổ sung rule nguồn 2026-07-22.\n\n---\n\n## 1. Cấu trúc bắt buộc\n\n```\n[0–3s]     HOOK          — bắt người xem dừng lướt\n[3–30s]    KHỐI HIGHLIGHT — nói HẾT lý do mua, dồn lên đầu\n[30s → …]  NỘI DUNG CHÍNH — chiều sâu, dành cho người thật sự quan tâm\n[cuối]     CTA           — lý do cụ thể để nhắn tin\n```\n\n### 1.1. HOOK — 1–3 giây\n- Chỉ có **1–3 giây** để người xem quyết định dừng hay lướt. Hook phải nằm trọn\n  trong khoảng đó, không có intro, không logo, không \"xin chào tôi là…\".\n- Vào thẳng bằng: con số cụ thể · nghịch lý · hình ảnh lạ · đúng câu khách hay hỏi.\n\n### 1.2. KHỐI HIGHLIGHT — 20–30 giây đầu\nTrong 20–30 giây đầu phải nói được **hết các ý highlight chính** về sản phẩm:\n\n| # | Nhóm ý bắt buộc |\n|---|---|\n| 1 | **USP** — điều làm khách chọn sản phẩm này |\n| 2 | **Ưu điểm vượt trội** |\n| 3 | **Công nghệ** |\n| 4 | **Vật liệu lọc** |\n| 5 | **Thiết kế** |\n| 6 | **App / vận hành thông minh** |\n\n→ Gộp lại phải trả lời được: **vì sao khách nên chọn mua sản phẩm này.**\n\n**Cách sản xuất:** khối này có thể cắt highlight từ trong nội dung chính đưa lên\nđầu — nhưng **nên quay riêng ngay từ đầu**, đỡ mất công cắt và nhịp gọn hơn.\nNhịp: mỗi ý ~4 giây, nói nhanh, cắt nhanh, mỗi ý một cảnh, **không dừng giải thích**.\n\n### 1.3. NỘI DUNG CHÍNH\n- Video chuyên gia **được phép dài 5–7 phút**. Khách thật sự quan tâm sẽ xem hết\n  vì đây là sản phẩm giá trị cao và họ đang cần hiểu sâu hơn trước khi xuống tiền.\n- Không cắt ngắn để \"hợp thuật toán\" — người xem hết chính là người sắp mua.\n- Chiều sâu là lợi thế cạnh tranh: xem `style-notes/chuyen-gia.md`.\n\n### 1.4. CTA\n- Phải có **lý do cụ thể và ít cam kết** để khách nhắn tin (không \"inbox để được\n  tư vấn\"). Tốt nhất: khách gửi vài thông tin đơn giản → nhận lại thứ có giá trị\n  ngay (con số, đánh giá tình trạng, gợi ý phương án).\n- CTA phải nối liền mạch nội dung vừa nói, không phải đoạn quảng cáo dán vào cuối.\n\n## 2. Định dạng\n\n- **Facebook Ads → dọc 9:16.** Không dùng TVC ngang (GWT đã xác nhận không ổn).\n- Caption Facebook: 2 dòng đầu = hook thứ hai, phải chứa con số hoặc nghịch lý.\n\n## 3. Tuyến nội dung mới phải KHÁC video cũ\n\nTrước khi viết, **đọc bảng `video_ads`** (Supabase `GWT-Masterdata`) để biết các\ntuyến đã làm. Tuyến mới bắt buộc có **điểm khác biệt và góc nhìn mới** — không lặp\nlại trục kể của video cũ (vd: nếu video cũ toàn đi \"tour thiết bị\" thì tuyến mới\nphải đổi trục).\n\n## 4. Làm thành SERIES\n\n- Mỗi tuyến là **một series quay liên tục nhiều tập**, không phải một tập lẻ.\n- Mỗi tập độc lập (xem lẻ vẫn hiểu) nhưng có móc nối sang tập sau.\n- Thiết kế để **quay gộp nhiều tập trong một buổi** (đổi áo giữa buổi).\n\n## 4b. ⭐ MỌI SỐ LIỆU PHẢI CÓ NGUỒN CHUẨN — `rules/nguon-dan-chung.md`\n\nKhông con số nào được lên hình nếu chưa qua **quy trình 4 bước** của rule nguồn:\n**liệt kê → gắn hạng A/B/C/D → xử lý → lưu hồ sơ**.\n\nBa điều dễ sai nhất, nhắc lại ở đây:\n1. ⛔ **Nội dung do AI sinh ra là hạng C** — kể cả khi nó nằm trong tài liệu nội bộ của\n   công ty. Đã có ca thật: bảng độ cứng theo tỉnh trong `[MKT] Content Research.md` sai\n   **5–7 lần** so với công bố của công ty cấp nước.\n2. ⛔ **Podcast/KOL là hạng C.** Nghiên cứu mà podcast **dẫn tên** mới là hạng A — phải\n   đi tìm đúng nghiên cứu đó.\n3. ⛔ **Không đặt cạnh nhau hai con số đo hai đại lượng khác nhau** (độ cứng theo CaCO₃\n   vs magie nguyên tố vs °dH).\n\n**Mỗi con số trên hình phải có thẻ nguồn** (tên cơ quan + năm, chữ nhỏ, hiện cùng lúc\nvới con số). Số đo của GWT phải kèm: *\"đo tại nhà khách, tại một thời điểm\"*.\n\n## 5. ⚠️ KHÔNG dùng VIEW để đánh giá hiệu quả hay để rút rule\n\n**View KHÔNG phải thước đo.** Lý do:\n- Lượng view của video ads phụ thuộc **ngân sách bơm quảng cáo**, không phản ánh\n  chất lượng nội dung.\n- Một video có thể có **nhiều link**; link lưu trong bảng dữ liệu chưa chắc là link\n  đang được đẩy ads → con số view gắn với link đó không nói lên điều gì.\n\n→ Khi phân tích video cũ hoặc rút bài học: **chỉ dùng nhãn hiệu quả do GWT xác\nnhận** (ra tiền / không hiệu quả / feedback thực tế), **tuyệt đối không dùng\nview/lượt xem** làm bằng chứng.\n\n**KPI thật:** số điện thoại · inbox · khách nhắc lại nội dung video khi tư vấn ·\nđơn chốt.\n",
  "video-loc-tong": "# RULE: Làm video về LỌC TỔNG (POE — Wholehouse Filtration)\n\n> RULE BẮT BUỘC, áp cho mọi nội dung (video, bài viết, kịch bản, telesales, tin nhắn)\n> nói về giải pháp lọc đầu nguồn GE. Áp CÙNG với `rules/ad-compliance-vn.md`\n> (luật quảng cáo thắng mọi rule khác) và **`rules/nguon-dan-chung.md`** (chuẩn nguồn\n> cho mọi số liệu — mục 1b dưới đây là số hạng A, nhưng vẫn phải lưu hồ sơ).\n> Nguồn quyết định: GWT — 2026-07-21 · bổ sung 2026-07-22.\n\n---\n\n## 1. KHÔNG bao giờ nói về một mã/bộ cụ thể\n\n**Nội dung lọc tổng chỉ nói về GIẢI PHÁP LỌC TỔNG CỦA GE — không nói về một sản\nphẩm, một unit, một thiết bị hay một mã bộ nào.**\n\n- ❌ KHÔNG được xuất hiện trong lời thoại/text overlay: `WH15A`, `WH30A`,\n  `WH15A ECO`, `WH30A ECO`, `GTEF-30A01-G`, `GTEC-15A01-G`, …\n- ❌ KHÔNG so sánh bộ này với bộ kia (\"WH30A mạnh hơn WH15A\").\n- ✅ Được nói: \"hệ thống lọc đầu nguồn GE\", \"giải pháp lọc tổng GE\",\n  \"hệ 3 cấp: tiền lọc – lọc trung tâm – làm mềm trung tâm\".\n\n**Lý do (ghi lại để người sau không phá rule):** các bộ chỉ khác nhau về **công\nsuất**, còn **công dụng như nhau**. Việc chọn bộ nào KHÔNG phụ thuộc tính năng\nkhác biệt để đem ra quảng cáo, mà phụ thuộc **nhu cầu sử dụng thực tế + ngân sách\ncủa khách hàng**. Nói mã cụ thể trong quảng cáo = làm khách tự chọn sai và làm mất\nbước tư vấn công suất.\n\n**Hệ quả tích cực — biến rule thành CTA:** vì không thể chọn hộ khách qua video,\nvideo lọc tổng có lý do tự nhiên để mời khách nhắn tin (\"cho tôi biết nhà mình\nmấy người, ở khu vực nào — bên tôi tính công suất phù hợp\").\n\n## 1b. SỐ LIỆU CHỐT — dùng đúng các con số này (GWT xác nhận 2026-07-21)\n\n| Hạng mục | Con số ĐÚNG | Ghi chú |\n|---|---|---|\n| Bảo hành | **12 tháng toàn bộ thiết bị** + **10 năm linh kiện cốt lõi** | Không nói \"bảo trì trọn đời\" (chưa xác nhận) |\n| Bảo trì định kỳ | 3 tháng/lần | |\n| ~~Bảo hiểm sản phẩm 1 tỷ~~ | ⛔ **KHÔNG DÙNG** | Gói bảo hiểm mua năm 2025, **đã không gia hạn** — bỏ khỏi mọi nội dung lọc tổng (GWT xác nhận 2026-07-21) |\n| Số chỉ tiêu cam kết | **15 chỉ tiêu** | Catalogue trang case study ghi 14 — SAI, cần sửa catalogue |\n| Quy chuẩn áp dụng | **QCVN 01-1:2024/BYT** (Thông tư 52/2024/TT-BYT, hiệu lực **01/7/2025**) | ⛔ KHÔNG có \"QCVN 01-1:2025/BYT\". Bỏ cụm \"cột A & B\" (là cách chia của bản 2018) |\n| Độ cứng cam kết | Dưới **17 mg/l** theo WQA | Quy chuẩn cho phép tới 300 mg/l |\n| Clo dư cam kết | Dưới **0,2 mg/l** | Không nói \"loại bỏ hoàn toàn clo\" |\n| Đo nước & khảo sát tận nhà | **MIỄN PHÍ** | Phải nêu điều kiện/phạm vi áp dụng nếu có giới hạn |\n\nTrên lời nói, gọi quy chuẩn là **\"quy chuẩn mới nhất, áp dụng từ giữa năm 2025\"**;\nsố hiệu đầy đủ để text overlay hiển thị (tránh đọc sai số hiệu trên camera).\n\n## 1c. NÓI VỀ KHOÁNG CHẤT — 3 điểm cần nói cho đúng (GWT xác nhận 2026-07-21)\n\n**(1) Hai tiêu chí khác nhau, KHÔNG mâu thuẫn.**\nGE cam kết **độ cứng < 17 mg/l (tính theo CaCO₃)** cho **nước sinh hoạt** sau lọc tổng.\nCác nguồn khoa học quốc tế nói về **magie nguyên tố (mg/L)** trong **nước uống**.\nĐây là **hai đại lượng khác nhau, cho hai loại nước khác nhau** → không xung đột.\nChỉ cần **không gộp chung vào một câu** để tránh người xem hiểu nhầm là cùng một thước đo.\n\n**(2) Kiến trúc hai hệ tách rời — nói chủ động, đừng chờ bị hỏi.**\nLàm mềm áp cho **nước SINH HOẠT** (bảo vệ bình nóng lạnh, đường ống, thiết bị, vải vóc);\n**nước ĂN UỐNG** đi tiếp qua **máy lọc uống ở điểm cuối** — nơi màng nano **giữ lại\nkhoáng**. Đây chính là câu trả lời cho mọi phản biện kiểu \"làm mềm là lấy hết khoáng\".\n\n**(3) \"Giữ 8 khoáng\" ĐÃ CÓ KẾT QUẢ ĐO — được nói.**\nNguồn: `Thông tin sản phẩm/GWT - Mineral Map - Thống kê hàm lượng khoáng update.md`\n(16 điểm đo thật). Số trung bình nước đầu ra máy lọc uống: **canxi ~3,9 mg/L** (cao nhất\n9,71) · **magie ~1,2** · **kali ~1,5** · **natri ~0,8** · **axit metasilicic ~8,4** ·\n**TDS trung bình 36** (dải 6–85) · **pH 6,7–8,5**.\n→ Khi trích phải ghi rõ **đây là số của nước qua MÁY LỌC UỐNG**, không phải nước sau lọc tổng.\n→ Cách nói chuẩn về natri: *\"nước ăn uống còn đi tiếp qua máy lọc uống ở điểm cuối; ở đó\nmột phần khoáng, trong đó có natri, **được giảm bớt — chứ không phải lấy sạch**.\"*\n\n## 1d. ⛔ KHÔNG NÓI RA — điểm yếu & thông tin nội bộ (GWT quyết 2026-07-21)\n\n| Không nói | Lý do | Nói thay bằng |\n|---|---|---|\n| **Số lượng/khối lượng vật liệu lọc** (kg than, lít resin, gram KDF, \"bao nhiêu hạt\") và **dung lượng trao đổi tính bằng grains** | Lượng vật liệu trong hệ GE **thấp hơn một số hệ khác** — đây là điểm yếu, không đưa lên kênh | Nói về **cơ chế**, **chất lượng vật liệu**, **sự kết hợp giữa các vật liệu**, **tuổi thọ tính bằng năm**, và **kết quả đo đầu ra** |\n| **Tên nhà cung cấp vật liệu** — gồm **Haycarb** (hãng than hoạt tính) và mọi tên hãng vật liệu khác | Thông tin chuỗi cung ứng, không cần thiết với khách | \"than gáo dừa Sri Lanka\", \"hạt nhựa trao đổi ion cao cấp\" |\n| **Chuyện tập đoàn GE tách thành 3 công ty** | Nhạy cảm | Không chủ động nêu. Nếu khách hỏi thẳng trong inbox → trả lời ngắn, trung thực, không mở rộng |\n| **Tên đơn vị \"mượn danh thương hiệu\"** | Rủi ro pháp lý + không cần thiết | Nói về **mô hình** (hàng lắp ráp / OEM) chứ không nêu tên |\n| **Quan hệ nhượng quyền thương hiệu GE ↔ GWT** | GWT quyết 2026-07-22: nhạy cảm, **gỡ khỏi video** (bỏ CH5 tập 12) | ⛔ Không nói trên video. ⚠️ Nhưng **vẫn phải có câu trả lời chuẩn** trong kịch bản inbox + tài liệu đào tạo sale — vì khách vẫn hỏi, chỉ là hỏi ở chỗ khác. ⛔ **Tuyệt đối không nói ngược lại** (không ngụ ý GWT là công ty con/chi nhánh của General Electric) |\n\n> ⛔ **Áp dụng tuyệt đối, kể cả khi host hỏi thẳng.** Ba câu hỏi hay dẫn người nói vào bẫy\n> này: *\"trong bình có bao nhiêu kg than?\"* · *\"dung lượng xử lý canxi bao nhiêu grains?\"* ·\n> *\"than của hãng nào?\"*. Cách trả lời đúng: **chuyển sang cơ chế + tuổi thọ + số đo đầu ra**\n> — *\"cái đáng hỏi không phải trong bình có bao nhiêu, mà là sau bình đo ra bao nhiêu.\"*\n>\n> 📌 **Lý do sâu hơn — vì sao đây là câu trả lời trung thực chứ không phải né tránh:**\n> giá trị của hệ GE nằm ở **sự kết hợp** (KDF đứng cạnh than để bảo vệ than; KDF đứng cạnh\n> resin để bảo vệ resin) và ở **tự động hoá chu trình tái sinh**, chứ không nằm ở khối lượng\n> vật liệu. So khối lượng là so sai trục — nhưng **không được nói câu đó theo kiểu hạ thấp\n> đối thủ** (K10 Đ8).\n>\n> ⚠️ **Một lưu ý cho người viết kịch bản:** rule này rất dễ bị phá **không phải bằng cách\n> nói ra**, mà bằng cách **dạy khách đi hỏi**. Đã xảy ra hai lần trong bản v1: tập 9 dạy\n> khách hỏi người bán *\"dung lượng bao nhiêu grains\"*, tập 14 dạy hỏi *\"trong bình có mấy\n> ký than\"* — tức là **tự đưa vũ khí cho người đi so sánh, nhắm đúng vào điểm yếu của\n> mình**. Khi viết bất kỳ beat \"cách chọn mua\" nào, **rà lại danh sách câu hỏi mình đang\n> dạy khách**.\n\n> 📌 **Nguyên tắc chung:** khi một thông số là **điểm yếu so với đối thủ**, không tự nêu ra\n> để rồi phải phòng thủ. Chuyển trọng tâm sang thứ mình mạnh: **cơ chế · sự kết hợp vật liệu ·\n> tuổi thọ · cam kết đầu ra đo được · dịch vụ**.\n\n## 2. Bán KẾT QUẢ ĐO ĐƯỢC, không bán thiết bị\n\nTrục nội dung ưu tiên: **chỉ số nước trước → sau**, không phải tour thiết bị.\n- Được nói: độ cứng (mg/l hoặc ppm), clo dư (mg/l), số chỉ tiêu đạt QCVN.\n- Số liệu phải là số thật (catalogue/biên bản đo/Supabase), có ghi bối cảnh\n  (\"đo tại một thời điểm bảo trì ở nhà khách\", \"độ cứng tham khảo theo tỉnh\").\n\n## 3. Ranh giới claim (rút từ 26 video cũ — xem `video_ads`)\n\n| Nhóm | Xử lý |\n|---|---|\n| **Claim sức khoẻ** — \"tốt cho sức khoẻ\", \"hết rụng tóc\", \"hết mụn\", \"gây ung thư\" | ⛔ **Cấm.** Nói thay bằng thứ **quan sát/đo được**: \"độ cứng về dưới 17mg/l theo WQA\", \"clo dư về 0\", \"hết cặn trắng trên kính tắm\". Khi cần nói về tác hại của một chất → **nêu ngưỡng quy chuẩn và lý do có ngưỡng** (WHO/QCVN), **không nêu tên bệnh** và không nói sản phẩm chữa/phòng bệnh |\n| **Cam kết tuyệt đối về clo** — \"loại bỏ hoàn toàn/100% clo\" | ⛔ Cấm. Nói \"clo dư về mức ≤ 0,2mg/l\" |\n| **So sánh đích danh đối thủ** — \"hơn hãng X\" | ⛔ Cấm trong video. Bộ tài liệu so sánh của anh Như **chỉ dùng nội bộ/đào tạo sale**. Trên video: so với **chính hiện trạng nhà khách** trước khi lắp, hoặc nói về **LOẠI công nghệ** |\n| **Từ tuyệt đối** — \"duy nhất\", \"triệt tiêu hoàn toàn cặn canxi\", \"sẵn sàng bồi thường\" | ✅ GWT khẳng định **đúng sự thật** (2026-07-21) → được dùng, **với điều kiện có tài liệu/căn cứ lưu trong hồ sơ** để xuất trình khi bị hỏi (K11 Đ8). Không dùng tuỳ tiện ở mọi câu |\n| **Nêu tên bên thứ ba** — Tesla, HSBC, Adidas, Nvidia, Coca-Cola, IBM | ✅ GWT xác nhận đúng → được nêu, **kèm tài liệu chứng minh lưu hồ sơ** (K10 Đ8) |\n| **Nêu tên đơn vị \"mượn danh thương hiệu\"** | ⛔ **Không đưa vào video** (GWT quyết 2026-07-21) — chỉ dùng nội bộ |\n\nCăn cứ: K9/K10/K11 Điều 8 + K1 Điều 19 Luật QC (xem `rules/ad-compliance-vn.md`).\n\n## 4. Định dạng video lọc tổng\n\n- **Chuyên gia phải có người hỏi thay khán giả** (hoặc nói với MỘT người cụ thể).\n  Đối chứng trong `video_ads` (theo nhãn GWT xác nhận, không theo view): bản có\n  phỏng vấn ra tiền (STT 8), bản độc thoại không ra tiền (STT 1, 27).\n- Cách nói & chiều sâu của chuyên gia: theo `style-notes/chuyen-gia.md`.\n- **Không dùng định dạng TVC ngang** cho phân phối Facebook (STT 22 — GWT xác nhận\n  không ổn). Ads Facebook: **dọc 9:16**. Cấu trúc hook/highlight/độ dài/series:\n  theo `rules/video-ads-general.md`.\n- Mọi thuật ngữ phải **quy đổi ngay** thành \"anh/chị khỏi phải làm gì / tiết kiệm\n  bao nhiêu / nhìn thấy gì trong nhà\". Thuật ngữ không giết video — thuật ngữ\n  KHÔNG quy đổi mới giết (STT 17 vs STT 1).\n- Phần lịch sử thương hiệu GE (Edison, Tesla, 140 năm) **không đặt ở đầu** — là\n  phần yếu nhất ở mọi video cũ. Dùng như bằng chứng phụ, đặt sau.\n\n## 5. Chỉ số đo hiệu quả\n\nKPI của video lọc tổng là **số điện thoại/inbox đổ về + đơn chốt**.\n\n⛔ **KHÔNG dùng lượt view để đánh giá hay để rút rule** — view phụ thuộc ngân sách\nbơm ads, và một video có thể có nhiều link (link lưu trong bảng chưa chắc là link\nđang chạy ads). Chỉ dùng **nhãn hiệu quả do GWT xác nhận** (ra tiền / không hiệu\nquả) và feedback thực tế. Chi tiết: `rules/video-ads-general.md` mục 5.\n",
};

/** `Work GWT/Quy trình/*.md`, khoá là TÊN FILE gốc (có dấu, có khoảng trắng). */
export const QUY_TRINH: Record<string, string> = {
  "Quy trình chuẩn bị quay video ": "# QUY TRÌNH CHUẨN BỊ QUAY VIDEO CHO CÔNG TY\n\n> **Mục đích:** tài liệu hướng dẫn nội bộ, giúp người mới vào (MR, content, sản xuất) hiểu và thực hiện đúng quy trình từ lúc lên ý tưởng đến lúc sẵn sàng bấm máy.\n> **Phạm vi áp dụng:** mọi buổi quay video marketing của công ty (kịch bản có người xuất hiện, demo sản phẩm, B-roll...).\n> **Lưu ý chung:** tất cả file làm việc (kịch bản, shot list, checklist...) lưu dưới định dạng `.md`. Người mới nên cài **Obsidian** để đọc và quản lý các file này thuận tiện hơn.\n\n---\n\n## Bước 1 — Lên ý tưởng và viết kịch bản\n\n- MR (Marketing) tìm hiểu thông tin đề tài, sản phẩm, insight khách hàng liên quan đến tập/video sắp quay.\n- Viết kịch bản bằng **tool viết kịch bản trong Marketing Kit**.\n- Lưu kịch bản dưới dạng file `.md`, đặt tên rõ ràng, dễ tra cứu (theo tập/chủ đề).\n\n---\n\n## Bước 2 — Chuẩn bị (khảo sát và tìm nguồn lực)\n\n### 2.1. Tìm địa điểm quay\n\n- Tìm các studio, quán cà phê, Airbnb có góc quay phù hợp qua Facebook, TikTok, Airbnb. Một số địa điểm tham khảo sẽ được bổ sung trong sheet riêng.\n- Sau khi chọn ra được các địa điểm ưng ý, **phải đến khảo sát trực tiếp**, kiểm tra các tiêu chí sau:\n  - Không gian yên tĩnh — nếu ồn ào sẽ không quay/chụp được.\n  - Cơ sở vật chất còn mới.\n  - Không gian thoáng đãng, không ẩm mốc, không chật hẹp hay bí bách.\n  - Không ở tầng quá cao mà phải đi bộ (vì sẽ phải bê vác nhiều đồ quay chụp nặng).\n  - Hỏi rõ về chính sách check-in sớm (để có thời gian setup) và check-out muộn (để có thể quay lâu hơn nếu phát sinh).\n  - Hỏi rõ có phát sinh chi phí gì liên quan đến việc quay/chụp tại địa điểm không.\n\n### 2.2. Tìm thuê thiết bị mic và đèn\n\n- Tìm địa chỉ thuê mic và đèn phù hợp — tham khảo liên hệ anh **Thành Cá** (thông tin liên hệ sẽ bổ sung).\n- Mic quay podcast ưu tiên: Shure, Rode Podmic,...\n- Yêu cầu bên cho thuê gửi hình ảnh cụ thể của thiết bị nếu có thể, để kiểm tra trước.\n\n### 2.3. Tìm trang phục phù hợp\n\n- Ưu tiên chất liệu vải mới, cứng cáp, dày dặn, form đẹp, trông sang trọng.\n- Không chọn đồ có chất liệu xấu, mỏng, nhăn nhúm, kém sang.\n\n---\n\n## Bước 3 — Chốt phương án và đặt lịch\n\n- Chốt địa điểm quay, đơn vị cho thuê mic/đèn, bản kịch bản chính thức, trang phục.\n- Đặt phòng/thuê địa điểm và hẹn lịch thuê thiết bị cụ thể sau khi đã chốt ngày quay.\n- Mua trang phục đã chọn.\n- Chuẩn bị và mua các vật dụng cần thiết khác để phục vụ buổi quay:\n  - **Trước khi mua**, kiểm tra trong kho xem đã có sẵn đồ có thể tận dụng chưa.\n  - Nếu kho không có, mới tiến hành đặt mua.\n- **Lên list các cảnh quay cần thiết** (đối với các video cần quay nhiều cảnh).\n- Lập **checklist các cảnh cần quay và việc cần làm** để tiện theo dõi trong buổi quay (VD: chụp thumbnail, quay cảnh trám...).\n\n---\n\n## Bước 4 — Trước ngày quay 1 ngày\n\n- Ra kho soạn sẵn các đồ cần mang đi quay, để riêng một góc để hôm sau các anh ở kho có thể ship trực tiếp ra địa điểm quay. Bao gồm:\n  - 2 đèn (chân, đế và hộp đèn).\n  - Chân máy quay.\n  - Các đồ cần thiết khác có thể tận dụng được từ kho.\n- **Sạc máy ảnh** (tìm tutorial trên YouTube về cách sạc đúng cách).\n- **Sạc mic**.\n- **Chuẩn bị thẻ nhớ** sẵn sàng.\n- Tạo sẵn một sheet để ghi lại nguồn (source) khi quay — lấy source nào ghi lại luôn, giúp tiết kiệm thời gian xem và duyệt lại sau này.\n- Xác nhận (confirm) lại lần cuối: địa điểm quay, đơn vị cho thuê mic/đèn, và các trang phục cần thiết đã chuẩn bị sẵn sàng.\n\n---\n\n## Bước 5 — Ngày quay\n\n- Book ship đồ quay từ kho tới địa điểm quay (lưu ý book **xe van** với đồ cồng kềnh); căn giờ book cho phù hợp vì xe van có thể đi chậm hơn bình thường.\n- Hỗ trợ anh quay chụp setup, chuẩn bị sẵn đồ đạc.\n- Luôn để ý tới các góc máy, dáng ngồi, trang phục — không để bị nhăn, lệch góc máy...\n- Nếu địa điểm quay không có sẵn nước uống hay đồ ăn nhẹ, nên chuẩn bị sẵn nước cho mọi người + đồ ăn nhẹ (nếu có).\n- Trong lúc quay, tới đâu ghi lại source dùng được tới đó, để tìm lại cho dễ.\n\n> *Mục dưới đây là đề xuất bổ sung, đang chờ duyệt trước khi đưa vào chính thức:*\n> - Mang theo pin dự phòng và thẻ nhớ dự phòng ra hiện trường (phòng hết pin/đầy thẻ giữa buổi quay).\n> - Cuối buổi quay, backup ngay source ra ổ cứng/cloud lưu trữ của công ty, tránh trường hợp mất/hỏng thẻ nhớ trước khi copy lại.\n> - Chụp lại hiện trạng địa điểm trước và sau khi quay (đối chiếu, tránh phát sinh tranh chấp chi phí với chủ địa điểm).\n> - Dọn dẹp, sắp xếp lại địa điểm như hiện trạng ban đầu trước khi rời đi.\n> - Có timeline/khung giờ quay cho từng cảnh để chủ động theo dõi tiến độ trong ngày, tránh trễ giờ trả địa điểm.\n\n---\n\n## Bước 6 — Sau ngày quay\n\n- Lấy lại thẻ nhớ từ anh quay chụp.\n- Nhờ cắt (cut) 1 frame hoặc 1 video ngắn để gửi cho anh design làm font/guideline.\n\n---\n\n## Ghi chú cho người mới\n\n- Toàn bộ tài liệu quy trình, kịch bản, checklist của công ty đều ở dạng `.md` — nên làm quen với Obsidian ngay từ đầu để tiện đọc, liên kết và tìm kiếm giữa các file.\n- Khi có thắc mắc về địa điểm, thiết bị hoặc liên hệ thuê đồ, hỏi người phụ trách trực tiếp trước khi tự quyết định, đặc biệt với các khoản phát sinh chi phí.\n",
  "Quy-trinh-editor-ngoai": "# QUY TRÌNH LÀM VIỆC VỚI EDITOR NGOÀI — tài liệu training người mới\n\n> **Dành cho:** nhân sự marketing GWT mới nhận việc sản xuất video (chưa cần biết dựng phim chuyên nghiệp).\n> **Đọc xong làm được gì:** tự chạy trọn một video từ ý tưởng → brief → bàn giao editor ngoài → nghiệm thu → thanh toán.\n> **Vai trò của bạn:** bạn KHÔNG phải editor. Bạn là **người chốt ý tưởng và làm bản nháp flow** để editor ngoài\n> hiểu đúng thứ mình muốn. Bản nháp xấu cũng được — miễn đúng flow.\n> Cập nhật: 2026-08-22.\n\n---\n\n## 0. Toàn cảnh 7 bước\n\n| Bước | Việc | Ai làm | Output bắt buộc | Thời gian tham khảo |\n|---|---|---|---|---|\n| 1 | Xác định định dạng, thời lượng, yêu cầu, **kịch bản (nhất là hook)** | Bạn | `kichban.md` đã duyệt | 0.5–1 ngày |\n| 2 | Chọn source trong kho video đã quay | Bạn | Folder `02_SOURCE/` + danh sách timecode | 0.5 ngày |\n| 3 | Gen voiceover (ElevenLabs / MiniMax) | Bạn | `voiceover.wav` (+ bản dự phòng) | 1–2 giờ |\n| 4 | Dựng **edit flow** (bản nháp brief bằng hình) | Bạn (Descript + DaVinci) | `draft.mp4` + `timeline.xml` + `subtitles.srt` | 0.5–1 ngày |\n| 5 | Đóng gói folder + brief + ref → gửi editor, **chốt deadline** | Bạn | Link folder + brief đã gửi | 1 giờ |\n| 6 | Nhận bài → revise tới khi ưng | Bạn ↔ Editor | Bản final duyệt | 2–5 ngày |\n| 7 | Thanh toán | Bạn | Xác nhận đã trả | — |\n\n**Nguyên tắc xuyên suốt:** *bước sau không sửa được lỗi của bước trước.* Kịch bản sai thì editor giỏi mấy cũng\nkhông cứu được. Đừng vội gửi editor khi bước 1–4 còn lỏng.\n\n**Luật bắt buộc phải đọc trước khi viết bất cứ chữ nào:**\n- [rules/ad-compliance-vn.md](../rules/ad-compliance-vn.md) — luật quảng cáo VN (thắng mọi rule khác)\n- [rules/video-ads-general.md](../rules/video-ads-general.md) — cấu trúc bắt buộc của video chạy ads\n- [rules/hook-video-playbook.md](../rules/hook-video-playbook.md) — cách làm hook giữ chân\n- [rules/video-loc-tong.md](../rules/video-loc-tong.md) — riêng video lọc tổng (POE): **không nêu mã bộ**\n- [rules/nguon-dan-chung.md](../rules/nguon-dan-chung.md) — mọi con số phải có nguồn\n\n---\n\n## Chuẩn bị trước khi bắt đầu (làm 1 lần)\n\n**Tài khoản cần xin quản lý:**\n- Google Drive: folder `MKT` (kho source) + quyền tạo folder mới\n- Ổ/NAS chứa footage camera GWT\n- ElevenLabs và/hoặc MiniMax (tài khoản team, **không tự đăng ký tài khoản cá nhân rồi tính tiền công ty**)\n- Descript (bản có Timeline Export nếu cần xuất XML)\n\n**Phần mềm cài trên máy:**\n- **Descript** — cắt video bằng cách cắt chữ (dùng cho video có người nói)\n- **DaVinci Resolve** (bản Free là đủ để làm draft) — dựng flow, chèn nhạc/SFX/text\n- (tuỳ chọn) After Effects — chỉ khi cần motion phức tạp; xem\n  [docs/10.8.2026_Workflow_Descript_DaVinci_AfterEffects.md](10.8.2026_Workflow_Descript_DaVinci_AfterEffects.md)\n\n---\n\n# BƯỚC 1 — Xác định định dạng, thời lượng, yêu cầu, kịch bản\n\nĐây là bước **quan trọng nhất**. Chốt xong 5 ô dưới mới được đi tiếp.\n\n### 1.1. Bảng chốt đề bài (điền trước khi viết kịch bản)\n\n| Hạng mục | Chốt gì | Mặc định GWT |\n|---|---|---|\n| **Kênh đăng** | FB Reel / TikTok / YouTube Shorts / YouTube dài / Zalo | Cross-post 4 nền tảng |\n| **Định dạng** | Tỉ lệ khung hình | **9:16 dọc** cho ads. TVC ngang 16:9 đã xác nhận không hiệu quả |\n| **Thời lượng** | Số giây/phút mục tiêu | Ads ngắn: 30–60s · Video chuyên gia: 5–7 phút được phép dài |\n| **Loại video** | Chuyên gia / người dùng / không lời / demo sản phẩm | Xem mix A1–A4 trong `CLAUDE.md` |\n| **Mục tiêu** | View rộng hay ra số điện thoại/inbox | KPI = SĐT + inbox, **không phải view** |\n\n> ⛔ **Không dùng lượt view để đánh giá hiệu quả** — view phụ thuộc ngân sách bơm ads.\n> Chỉ dùng nhãn hiệu quả do GWT xác nhận (xem `rules/video-ads-general.md`).\n\n### 1.2. Kịch bản\n\nViết theo khung 3 lớp trong [docs/script-template.md](script-template.md):\n\n```\nLỚP A — Voice-over   (lời sẽ đọc)\nLỚP B — Text overlay (chữ hiện trên màn hình)\nLỚP C — Shot list    (hình gì chạy dưới lời đó)\n```\n\nCó thể nhờ Claude viết nháp bằng skill `write_script` (số liệu tự lấy từ Supabase, tự áp luật QC),\nnhưng **bạn là người chốt**, không copy máy móc.\n\nCấu trúc bắt buộc cho video chạy ads:\n\n```\n[0–3s]     HOOK           — bắt người xem dừng lướt\n[3–30s]    KHỐI HIGHLIGHT — nói HẾT lý do mua, dồn lên đầu (6 nhóm ý)\n[30s → …]  NỘI DUNG CHÍNH — chiều sâu cho người thật sự quan tâm\n[cuối]     CTA            — lý do cụ thể để nhắn tin\n```\n\n### 1.3. HOOK — viết riêng, kỹ nhất\n\nHook là **đơn vị riêng**, nên quay riêng, KHÔNG lấy đoạn chuyên gia ngồi nói làm mở màn.\nĐọc kỹ [rules/hook-video-playbook.md](../rules/hook-video-playbook.md). Rút gọn 4 luật quan trọng nhất:\n\n1. **Bắt đầu bằng hành động vật lý**, không bằng lời dẫn (đo TDS/độ cứng, bổ đôi lõi lọc đã dùng,\n   rót 2 cốc nước trước–sau, thả giấy test đổi màu).\n2. **Câu đầu tiên = kết quả hoặc câu hỏi tò mò**, không phải bối cảnh.\n   ❌ \"Trên thị trường có nhiều hãng, GE có lợi thế gì?\" → ✅ \"Nước nhà bạn đang cứng cỡ nào?\"\n3. **Có con số cụ thể đập ngay** trong 3 giây đầu.\n4. **Nhịp cắt dốc rồi thả dần**: 15–30s đầu dưới 1s/cut, sau đó giãn ra rồi vào shot dài cho chuyên gia nói.\n\n**Checklist chốt bước 1 — chưa tick đủ thì chưa qua bước 2:**\n- [ ] Đã chốt kênh + tỉ lệ + thời lượng + loại video + mục tiêu\n- [ ] Kịch bản đủ 3 lớp A/B/C\n- [ ] Hook viết riêng, có hành động vật lý + con số trong 3s đầu\n- [ ] Mọi số liệu khớp Supabase / có nguồn theo `rules/nguon-dan-chung.md`\n- [ ] Không có claim y khoa, không \"số 1 / tốt nhất / duy nhất\", không nêu tên đối thủ\n- [ ] Nếu là lọc tổng: **không nhắc mã bộ nào** (WH15A, WH30A, ECO…)\n- [ ] Người phụ trách đã duyệt kịch bản\n\n---\n\n# BƯỚC 2 — Chọn source trong kho video đã quay\n\nMục tiêu: **không quay mới nếu kho đã có**. Cắt lại từ video cũ hoàn toàn hợp lệ.\n\n### 2.1. Hai kho phải lục\n\n1. **Folder camera GWT** (ổ/NAS footage gốc) — chất lượng cao nhất, ưu tiên số 1\n2. **Folder Drive MKT** — video đã dựng, đã đăng, b-roll rời\n\n### 2.2. Quy tắc chất lượng\n\n- Ưu tiên **4K > 2K > 1080p**. Càng cao càng tốt vì editor còn crop/reframe về 9:16 và zoom.\n- **Lấy file gốc, không lấy file đã nén đăng mạng** (video tải lại từ Facebook/TikTok đã mất chất lượng\n  + có watermark). Chỉ dùng bản đăng mạng khi không còn nguồn nào khác.\n- Kiểm nhanh trước khi chọn: độ phân giải, frame rate, có tiếng không, tiếng có lệch hình không.\n- Cùng một video **không trộn nhiều frame rate** nếu tránh được — báo editor nếu buộc phải trộn.\n\n### 2.3. Ghi lại timecode — bắt buộc\n\nKhông copy nguyên file 40 phút rồi bảo editor \"tự tìm\". Lập bảng:\n\n| # | File gốc | Timecode | Nội dung | Dùng cho |\n|---|---|---|---|---|\n| 1 | `A7S_C0043.MP4` | 00:12:31 – 00:12:48 | Cận tay bổ đôi lõi lọc | Hook |\n| 2 | `A7S_C0051.MP4` | 00:03:10 – 00:03:52 | Anh Như giải thích tái sinh | Nội dung chính |\n\nLưu bảng này thành `02_SOURCE/danh-sach-source.md` — đây là thứ editor đọc đầu tiên.\n\n**Checklist bước 2:**\n- [ ] Đủ hình cho **mọi** dòng trong Shot list (lớp C) — thiếu chỗ nào ghi rõ \"CẦN QUAY THÊM\"\n- [ ] Đã copy file gốc (không phải bản nén) vào `02_SOURCE/`\n- [ ] Có bảng timecode\n- [ ] Có ít nhất 2–3 phương án hình cho hook để editor chọn\n\n---\n\n# BƯỚC 3 — Gen voiceover\n\nDùng khi kịch bản cần lời đọc (video không lời, video minh hoạ, phần dẫn chuyện).\nVideo chuyên gia nói trực tiếp thì **giữ tiếng thật**, không thay bằng AI.\n\n> 📝 Thuật ngữ: gen giọng đọc từ chữ = **Text-to-Speech (TTS)**.\n> *Speech-to-text* là chiều ngược lại (từ tiếng ra chữ) — cái đó dùng ở bước 4, khi Descript lấy transcript.\n\n### 3.1. Chọn tool\n\n| Tool | Mạnh | Dùng khi |\n|---|---|---|\n| **ElevenLabs** | Giọng tự nhiên, kiểm soát cảm xúc, ổn định | Voice chính, video quan trọng |\n| **MiniMax** | Giọng tiếng Việt/châu Á khá, rẻ hơn | Thử nhiều phương án, video số lượng lớn |\n\n### 3.2. Cách làm\n\n1. Dán **đúng lớp A (Voice-over)** của kịch bản, không dán cả kịch bản.\n2. Chọn giọng khớp tuyến nội dung:\n   - Chuyên gia/kỹ thuật → nam, trung niên, chậm, chắc\n   - Người dùng/đời thường → trẻ hơn, nhịp nhanh, thân mật\n3. **Gen 2–3 phương án giọng khác nhau** rồi nghe lại chọn, đừng lấy bản đầu tiên.\n4. Sửa chữ để sửa giọng đọc: chấm phẩy điều khiển nhịp ngắt; số viết ra chữ nếu đọc sai\n   (`1–3 mg/l` → \"một đến ba mi-li-gam trên lít\"); tên riêng viết theo cách đọc.\n5. Xuất **WAV** (không MP3) cho editor. MP3 chỉ dùng để nghe duyệt nhanh.\n6. Đặt tên: `voiceover_v1.wav`, sửa lời thì lên `v2` — **không ghi đè**.\n\n**Checklist bước 3:**\n- [ ] Nghe lại toàn bộ, không có chỗ đọc sai số/tên/thuật ngữ\n- [ ] Nhịp khớp thời lượng mục tiêu (đọc thử, bấm giờ)\n- [ ] Xuất WAV + đặt tên có version\n- [ ] Lưu kèm file text đã dùng để gen (`voiceover_v1.txt`) để lần sau gen lại y hệt\n\n---\n\n# BƯỚC 4 — Dựng EDIT FLOW (bản nháp để brief editor)\n\n**Mục đích duy nhất:** để editor ngoài **hiểu được idea mình muốn**.\nKhông cần đẹp, không cần chỉnh màu, không cần transition xịn. Cần **đúng flow**.\n\nBa thứ phải nhìn ra được trong bản nháp: **nhạc ở đâu · SFX ở đâu · chữ hiện lúc nào, nội dung gì.**\n\n## 4.A — Descript (video chuyên gia / có người nói)\n\nDùng Descript để cắt sạch lời: bỏ \"ừ, ờm\", câu lặp, câu hỏng, khoảng lặng dài.\n\n**Quy trình chuẩn (làm đúng thứ tự):**\n\n1. **Đẩy video lên** Descript.\n2. **Tạo bản copy để edit** — luôn giữ bản gốc nguyên vẹn để còn quay lại được.\n3. `AI Tools` → **Edit for clarity** → chọn mức **cao nhất** → **Remove ignored texts**\n   *(dọn filler words, câu lặp, đoạn thừa)*\n4. `AI Tools` → **Shorten Word gaps** → **Gap more than 0.5s → shorten to 0.3s** → **All**\n   *(rút khoảng lặng, video đỡ lê thê)*\n5. **Đưa transcript cho Claude** làm 2 việc:\n   - **Chọn câu trong các đoạn nói lặp** — chuyên gia thường nói một ý 2–3 lần; hỏi Claude bản nào\n     gọn và rõ nhất để giữ, các bản còn lại cắt.\n   - **Check lỗi chính tả** trong transcript (transcript sai → caption sai).\n6. **Chọn All** → `Change Layout` → **Captions** *(bật phụ đề để soát bằng mắt)*\n7. **Xem lại 1 lượt từ đầu đến cuối** rồi **cut final** — đây là lúc phát hiện chỗ cắt vấp,\n   câu bị cụt, chuyển ý gãy.\n8. `AI Tools` → **Create clip / highlight reel** — cho Descript đề xuất các đoạn hay nhất,\n   dùng làm gợi ý cho khối highlight và cho các clip cắt ngắn. *(Xem ví dụ: POE-1)*\n\n**Xuất từ Descript** (chi tiết: [docs/10.8.2026_Workflow_Descript_DaVinci_AfterEffects.md](10.8.2026_Workflow_Descript_DaVinci_AfterEffects.md)):\n- `Export → Timeline → Premiere (.xml)` → được `timeline.xml` để mở trong DaVinci\n- `Export → Subtitles → SubRip (.srt)` → được `subtitles.srt`\n  (gợi ý: Show speakers OFF · ~35–42 ký tự/dòng · tối đa 2 dòng)\n- ⛔ **Không burn phụ đề chết vào video.** Giữ video và `.srt` rời để còn sửa typo, đổi font, đổi màu.\n\n> Sau bước này coi như **SCRIPT LOCK** — chốt lời nói, không đổi cấu trúc lời nữa.\n\n## 4.B — DaVinci Resolve (dựng flow)\n\nMở `timeline.xml` từ Descript (hoặc dựng tay nếu video không lời), rồi làm **vừa đủ để nhìn ra flow**:\n\n| Làm | Không làm ở bước này |\n|---|---|\n| Ráp đúng thứ tự shot theo kịch bản | Chỉnh màu / grading |\n| Chèn nhạc nền, đánh dấu chỗ fade | Transition cầu kỳ |\n| Chèn sound effect ở các điểm nhấn | Motion graphic phức tạp |\n| Chèn **text dự kiến** (nội dung + vị trí + thời điểm) | Căn chỉnh font/kerning hoàn hảo |\n| Cắm voiceover đúng nhịp | Render chất lượng cao |\n\nLayout track gợi ý:\n\n```\nSUBTITLE  [ Subtitle Track — import subtitles.srt ]\nV3        [ Text dự kiến ]\nV2        [ B-roll ]\nV1        [ A-roll ]\nA1        [ Lời thoại / voiceover ]\nA2        [ SFX ]\nA3        [ Music ]\n```\n\n**Mẹo cực hữu ích:** ở những chỗ bạn muốn editor làm gì đó mà mình chưa làm được, cứ **chèn một ô chữ đỏ**\nghi thẳng lên hình: *\"CHỖ NÀY ZOOM VÀO MÁY ĐO\"*, *\"CẦN SFX WHOOSH\"*, *\"TEXT: 1–3 mg/l, đỏ → xanh\"*.\nEditor đọc bản nháp còn nhanh hơn đọc brief chữ.\n\nXuất bản nháp: `draft_v1.mp4`, H.264, 1080p là đủ.\n\n## 4.C — Tìm nhạc\n\n- Nguồn: YouTube (kênh no-copyright), **HelloThematic**, Epidemic Sound, Artlist, thư viện nhạc GWT (nếu có).\n- Có thể copy link nhạc dán lên **y2mate.com** để tải về nhanh cho bản nháp.\n- ⚠️ **Chỉ dùng nhạc thật sự no-copyright / đã có license.** Lưu lại link nguồn + dòng điều khoản\n  (\"free to use\", \"no copyright\") vào `05_ASSETS/MUSIC/nguon-nhac.txt`. Nếu tác giả yêu cầu ghi credit\n  thì phải ghi trong caption khi đăng. Nhạc dính bản quyền → video bị tắt tiếng hoặc gỡ, mất luôn ngân sách ads.\n- Chọn nhạc theo tuyến: hook cần energy; đến đoạn chuyên gia nói thì **fade out** để tiếng sạch\n  (fade dần, không cắt phựt).\n\n## 4.D — Font và text\n\n- **Ưu tiên: xin guideline chữ từ anh designer** (font, cỡ, màu, khoảng cách an toàn) — dùng thống nhất mọi video.\n- Chưa có guideline → lên [Google Fonts](https://fonts.google.com) chọn font **có hỗ trợ tiếng Việt đầy đủ**\n  (bắt buộc gõ thử: ắ ằ ẳ ễ ộ ợ ữ — nhiều font thiếu dấu, vỡ chữ).\n- Phân vai màu cho chữ, đừng để phụ đề một màu đều: ví dụ **đỏ = con số vấn đề**,\n  **xanh = kết quả sau lọc**, **trắng = tên bước**.\n- Chữ phải nằm trong vùng an toàn — tránh mép dưới (bị che bởi caption/nút của Facebook, TikTok).\n- Gửi kèm **file font** cho editor nếu dùng font không phổ biến.\n\n**Checklist bước 4:**\n- [ ] Descript đã lock script, đã soát chính tả\n- [ ] Có `timeline.xml` + `subtitles.srt`, phụ đề không burn vào hình\n- [ ] Bản nháp DaVinci nhìn ra được: nhạc ở đâu, SFX ở đâu, text nào hiện lúc nào\n- [ ] Ghi chú đỏ tại mọi chỗ cần editor xử lý\n- [ ] Nhạc đã lưu nguồn + license\n- [ ] Font đã kiểm dấu tiếng Việt\n\n---\n\n# BƯỚC 5 — Đóng gói, brief và chốt deadline\n\n## 5.1. Cấu trúc folder bàn giao (upload Drive, share quyền xem/tải)\n\n```\n20260822_POE_chuyen-gia-do-cung_9x16_v1/\n├── 00_BRIEF/\n│   ├── brief.md              ← file quan trọng nhất\n│   ├── kichban.md\n│   └── guideline-text.pdf    (nếu có)\n├── 01_REF/                   ← video tham khảo (link hoặc file)\n├── 02_SOURCE/\n│   ├── danh-sach-source.md   ← bảng timecode\n│   └── (file gốc 4K/2K)\n├── 03_VOICEOVER/\n│   ├── voiceover_v1.wav\n│   └── voiceover_v1.txt\n├── 04_DRAFT/\n│   ├── draft_v1.mp4          ← bản nháp flow\n│   ├── timeline.xml\n│   └── subtitles.srt\n├── 05_ASSETS/\n│   ├── MUSIC/ (+ nguon-nhac.txt)\n│   ├── SFX/\n│   ├── LOGO/\n│   └── FONT/\n└── 06_EXPORT/                ← editor trả bài vào đây\n```\n\n## 5.2. Brief phải nói rõ 6 nhóm\n\nKhông brief miệng. Không brief rải rác qua chat. **Viết ra file, gửi 1 lần, đủ 6 nhóm:**\n\n1. **Màu** — tông muốn (trong trẻo/sạch/xanh mát hay ấm/cao cấp), tham chiếu video ref nào\n2. **Cách edit** — nhịp cắt (hook dưới 1s/cut, thân bài giãn ra), reframe 9:16, có zoom/punch-in không\n3. **Transition** — dùng loại nào, tần suất; nói rõ nếu **không muốn** transition loè loẹt\n4. **Sound effect** — chỗ nào cần, kiểu gì (whoosh chuyển cảnh, ting cho con số, impact cho hook)\n5. **Text** — font, màu theo vai, vị trí, thời điểm; phụ đề full hay chỉ text nhấn\n6. **Ref video** — gửi **link cụ thể + ghi rõ lấy gì từ đó**: *\"lấy nhịp cắt hook của video này\"*,\n   *\"lấy kiểu chữ của video kia\"*. Ref không ghi chú = editor đoán sai.\n\nTemplate brief copy-paste: **Phụ lục A** ở cuối tài liệu.\n\n## 5.3. Chốt deadline\n\n- Nói rõ **ngày + giờ** nhận bài, không nói \"cuối tuần nhé\".\n- Chốt luôn **số vòng revise nằm trong giá** (thường 2 vòng) và **thời gian mỗi vòng** (24–48h).\n- Xác nhận lại giá trước khi editor bắt tay làm (xem bước 7) — không để đến lúc trả bài mới bàn tiền.\n- Yêu cầu editor **xác nhận đã nhận đủ file và hiểu brief** trước khi bắt đầu. Thiếu gì hỏi ngay\n  trong 24h đầu, không phải sát deadline.\n\n**Checklist bước 5:**\n- [ ] Folder đủ 6 mục, đã share quyền và **kiểm tra link mở được từ máy khác**\n- [ ] Brief đủ 6 nhóm, có ref kèm ghi chú\n- [ ] Deadline có ngày + giờ\n- [ ] Đã chốt giá + số vòng revise\n- [ ] Editor đã xác nhận nhận đủ file\n\n---\n\n# BƯỚC 6 — Nhận bài và revise\n\nNhận bản đầu tiên → **xem hết một lượt không dừng** (cảm nhận như người xem thật), rồi mới xem lượt hai\nđể ghi lỗi theo timecode.\n\n### 6.1. Duyệt theo 7 yếu tố — luôn theo đúng thứ tự này\n\n| # | Yếu tố | Hỏi gì |\n|---|---|---|\n| 1 | **Hook** | 3 giây đầu có giữ được không? Có hành động + con số không? Hook hỏng thì phần còn lại vô nghĩa |\n| 2 | **Voiceover** | Rõ chưa? To nhỏ có đều? Có bị nhạc át? |\n| 3 | **Nhạc** | Đúng tông? Có fade out khi vào đoạn nói? Có to quá không? |\n| 4 | **Sound effect** | Có đúng chỗ? Có bị lạm dụng thành ồn? |\n| 5 | **Transition** | Có mượt? Có bị loè loẹt/lỗi thời? |\n| 6 | **Text** | Đúng chính tả? Đủ dấu tiếng Việt? Nằm trong vùng an toàn? Kịp đọc không? |\n| 7 | **Tổng thể** | Màu nhất quán? Không frame đen? Không mất tiếng? Đúng tỉ lệ + thời lượng? |\n\n### 6.2. Cách ghi feedback (quyết định số vòng revise)\n\n**Luôn ghi theo timecode + nói rõ muốn gì**, không nói cảm tính:\n\n❌ \"Đoạn đầu chưa được, làm lại cho hay hơn\"\n✅ `00:02` — chữ \"1–3 mg/l\" hiện chậm 0.5s so với lúc nói, đẩy lên sớm hơn\n✅ `00:14` — nhạc át tiếng anh Như, hạ nhạc xuống khoảng 60%\n✅ `00:31` — transition xoay quá mạnh, đổi thành cắt thẳng\n\n**Gom feedback thành 1 lần/vòng.** Nhắn lắt nhắt 20 tin trong 3 ngày là cách nhanh nhất để\nmất thiện cảm của editor và đẩy dự án trễ.\n\n### 6.3. Kiểm tra pháp lý trước khi duyệt final — bắt buộc\n\n- [ ] Không có claim kiểu thuốc/chữa bệnh\n- [ ] Không \"số 1 / tốt nhất / duy nhất\" thiếu căn cứ\n- [ ] Không nêu tên/nhãn đối thủ (nếu lỡ xuất hiện trong hình → làm mờ)\n- [ ] Số liệu khớp Supabase (bảo hành, số lõi, chu kỳ thay); **không nêu giá / công dụng chưa có chứng nhận**\n- [ ] Video lọc tổng: không xuất hiện mã bộ cụ thể\n- [ ] Nhạc có license; credit (nếu cần) đã chuẩn bị cho caption\n\n### 6.4. Nghiệm thu\n\nYêu cầu editor gửi bản final:\n- Đúng tỉ lệ (9:16) + đúng thời lượng chốt\n- H.264 MP4, 1080p trở lên, không watermark\n- Kèm **bản không phụ đề** (nếu định cross-post nền tảng khác có caption riêng)\n- Kèm **project file** nếu đã thoả thuận (nên thoả thuận từ đầu — sau này sửa nhỏ đỡ phải gọi lại editor)\n\nLưu bản final vào `06_EXPORT/` + copy về Drive MKT.\n\n---\n\n# BƯỚC 7 — Thanh toán\n\n### Rate tham khảo\n\n| Loại | Rate |\n|---|---|\n| Video **dưới 1 phút** | **300.000đ** |\n| Video **trên 1 phút** | **400.000đ** |\n\n### Nguyên tắc\n\n- **Chốt giá TRƯỚC khi editor bắt đầu**, không phải sau khi trả bài.\n- Giá trên đã bao gồm **2 vòng revise**. Vòng thứ 3 trở đi, hoặc **đổi yêu cầu so với brief ban đầu**\n  (đổi kịch bản, đổi nhạc toàn bộ, đổi tuyến) → thương lượng phụ phí. Đây là lý do bước 1–5 phải chắc:\n  brief lỏng thì tiền phát sinh là lỗi của mình, không phải của editor.\n- Thanh toán sau khi **duyệt final**, đúng hạn đã hẹn. Giữ mối editor tốt quan trọng hơn 100k.\n- Lưu chứng từ: nội dung chuyển khoản ghi rõ `<tên video> - <ngày>`, lưu ảnh xác nhận vào folder dự án\n  hoặc file theo dõi chi phí của MKT.\n- Ghi lại vào bảng theo dõi: tên video · editor · rate · số vòng revise · đúng/trễ hạn · chất lượng.\n  Sau 5–10 video bạn sẽ biết nên giao ai loại nào.\n\n---\n\n# Lỗi người mới hay mắc\n\n| Lỗi | Hậu quả | Cách tránh |\n|---|---|---|\n| Gửi editor khi kịch bản chưa chốt | Sửa vòng vòng, phát sinh phí | Tick đủ checklist bước 1 |\n| Copy nguyên file 40 phút, bảo \"tự tìm đoạn hay\" | Editor cắt sai ý, trễ hạn | Bảng timecode ở bước 2 |\n| Dùng video tải lại từ Facebook/TikTok làm source | Mờ, có watermark, không cứu được | Luôn lấy file gốc từ camera/Drive |\n| Bản nháp làm quá kỹ (chỉnh màu, motion) | Mất 2 ngày làm trùng việc của editor | Nháp chỉ cần đúng flow |\n| Brief miệng / brief rải rác qua chat | Editor hiểu sai, cãi nhau lúc nghiệm thu | Brief 1 file, đủ 6 nhóm |\n| Gửi ref mà không nói lấy gì từ ref | Editor bắt chước nhầm chỗ | Ref phải kèm ghi chú |\n| Feedback cảm tính \"chưa hay lắm\" | Revise vô tận | Timecode + yêu cầu cụ thể |\n| Nhắn feedback lắt nhắt nhiều ngày | Trễ hạn, editor nản | Gom 1 lần/vòng |\n| Quên kiểm pháp lý trước khi đăng | Bị gỡ bài, rủi ro phạt | Checklist 6.3 |\n| Dùng nhạc \"thấy trên mạng ai cũng dùng\" | Tắt tiếng/gỡ video, mất tiền ads | Lưu link + license |\n| Burn phụ đề chết vào video | Sai một chữ phải render lại toàn bộ | Giữ `.srt` rời |\n\n---\n\n# Lộ trình training tuần đầu\n\n| Ngày | Làm gì |\n|---|---|\n| **1** | Đọc tài liệu này + 4 file rule ở mục 0. Xin đủ tài khoản, cài Descript + DaVinci. Xem 5 video GWT đã đăng và tự chấm theo 7 yếu tố ở mục 6.1 |\n| **2** | Lục 2 kho source, làm quen cấu trúc folder. Tự lập bảng timecode cho **một video đã đăng** (làm ngược để hiểu cách chọn source) |\n| **3** | Descript: chạy trọn 8 bước mục 4.A trên một file phỏng vấn cũ. Xuất `timeline.xml` + `subtitles.srt` |\n| **4** | DaVinci: mở XML, dựng flow nháp cho video đó — chèn nhạc, SFX, text dự kiến, ghi chú đỏ. Gen thử voiceover 2 phương án trên ElevenLabs/MiniMax |\n| **5** | Viết brief hoàn chỉnh theo Phụ lục A cho video đó → đưa người phụ trách chấm. Đạt thì được giao video thật, có người kèm ở vòng revise đầu |\n\nSau 3 video chạy trọn quy trình có người kèm → tự chạy độc lập.\n\n---\n\n# PHỤ LỤC A — Template brief gửi editor (copy nguyên, điền vào)\n\n```markdown\n# BRIEF VIDEO — <tên video>\n\n## 1. Thông tin chung\n- Mã dự án: 20260822_POE_chuyen-gia-do-cung_9x16_v1\n- Kênh đăng: Facebook Reel + TikTok + YouTube Shorts\n- Tỉ lệ: 9:16 dọc\n- Thời lượng mục tiêu: 45–60 giây\n- Deadline: 17:00 thứ Sáu 29/08/2026\n- Rate: 300.000đ (dưới 1 phút), gồm 2 vòng revise\n\n## 2. Mục tiêu video\n<1–2 câu: video này muốn người xem hiểu gì / làm gì>\n\n## 3. File trong folder\n- 00_BRIEF/kichban.md — kịch bản 3 lớp (lời / chữ / hình)\n- 02_SOURCE/danh-sach-source.md — bảng timecode các đoạn cần dùng\n- 03_VOICEOVER/voiceover_v1.wav\n- 04_DRAFT/draft_v1.mp4 — BẢN NHÁP FLOW, xem cái này trước\n- 04_DRAFT/timeline.xml + subtitles.srt\n- 05_ASSETS/ — nhạc, SFX, logo, font\n\n## 4. HOOK (0–3s) — phần quan trọng nhất\n- Hình: <mô tả>\n- Lời: <câu thoại>\n- Chữ: <text + màu>\n- Yêu cầu: nhịp cắt dưới 1s/cut, nhạc energy vào ngay từ frame đầu\n\n## 5. Màu\n<trong trẻo / sạch / xanh mát — hoặc ấm, cao cấp>. Tham chiếu: ref #1.\nDa người phải tự nhiên, không đẩy xanh quá tay.\n\n## 6. Cách edit\n- Nhịp: 0–30s cắt dồn, sau đó giãn dần, vào shot dài khi chuyên gia nói\n- Reframe 9:16, ưu tiên giữ mặt/tay trong khung an toàn\n- Được punch-in/zoom nhẹ ở các câu nhấn\n\n## 7. Transition\n<vd: chủ yếu cắt thẳng; whoosh nhẹ chỉ ở 2 chỗ chuyển chương. KHÔNG dùng transition xoay/glitch>\n\n## 8. Sound effect\n- 00:01 impact khi <hành động>\n- Mỗi lần con số hiện lên: ting nhẹ\n- Nhạc fade out từ 00:12 khi chuyên gia bắt đầu nói\n\n## 9. Text\n- Font: <tên font> (file trong 05_ASSETS/FONT/)\n- Đỏ = con số vấn đề · Xanh = kết quả sau lọc · Trắng = tên bước\n- Chữ tránh 15% mép dưới (bị UI nền tảng che)\n- Phụ đề: <full câu / chỉ text nhấn> — dùng subtitles.srt, KHÔNG tự gõ lại\n\n## 10. Video tham khảo\n| # | Link | Lấy gì từ ref này |\n|---|---|---|\n| 1 | <link> | Nhịp cắt + cách chèn số ở hook |\n| 2 | <link> | Kiểu chữ và cách chữ xuất hiện theo nhịp |\n\n## 11. KHÔNG được làm\n- Không burn phụ đề chết (giữ track riêng)\n- Không để lộ nhãn hiệu đối thủ (làm mờ nếu có)\n- Không thêm chữ/lời không có trong kịch bản\n- Không đổi nhạc khác nếu chưa hỏi\n\n## 12. Bàn giao\n- MP4 H.264, 1080p+, 9:16, không watermark → 06_EXPORT/\n- Kèm bản không phụ đề\n- Kèm project file\n```\n\n---\n\n# PHỤ LỤC B — Template feedback revise\n\n```markdown\n# REVISE VÒNG <1/2> — <tên video> — <ngày>\n\nTổng thể: <1 câu — cái gì đã ổn, đừng chỉ chê>\n\n| Timecode | Vấn đề | Muốn sửa thành |\n|---|---|---|\n| 00:02 | Chữ \"1–3 mg/l\" hiện chậm hơn lời nói ~0.5s | Đẩy sớm, khớp đúng lúc phát âm |\n| 00:14 | Nhạc át tiếng anh Như | Hạ nhạc còn ~60%, fade từ 00:12 |\n| 00:31 | Transition xoay quá mạnh | Đổi thành cắt thẳng |\n| 00:48 | Sai chính tả \"khoáng chât\" | \"khoáng chất\" |\n\nGiữ nguyên (đã tốt, đừng sửa): <liệt kê>\nHạn gửi lại: <ngày giờ>\n```\n\n---\n\n# PHỤ LỤC C — Checklist QC cuối cùng trước khi đăng\n\n- [ ] Xem lại **trọn vẹn một lượt** từ đầu đến cuối trên **điện thoại** (không phải màn hình máy tính)\n- [ ] Đúng tỉ lệ 9:16, đúng thời lượng\n- [ ] Hook 3 giây đầu đứng vững cả khi xem không có tiếng\n- [ ] Không typo, dấu tiếng Việt đủ, chữ không lỗi font\n- [ ] Chữ không bị UI nền tảng che\n- [ ] Tiếng không rè, không clip, nhạc không át lời\n- [ ] Không frame đen, không missing media, không watermark\n- [ ] Màu nhất quán giữa các shot\n- [ ] Đã qua checklist pháp lý mục 6.3\n- [ ] Caption từng nền tảng đã viết riêng (2 dòng đầu = hook thứ hai, có con số hoặc nghịch lý)\n- [ ] File final đã lưu Drive MKT\n",
};
